local config = {
  ui_story_5068_50680101_1_dialog_content = "<color=#e8d9bb><size=50>Batida!!!</size></color>",
  ui_story_5068_50680101_2_dialog_content = "(... Por que...)",
  ui_story_5068_50680101_3_dialog_content = "Ai!",
  ui_story_5068_50680101_4_dialog_content = "Por que essa louca morde todo mundo que vê?! Ainda bem que reagi rápido!",
  ui_story_5068_50680101_5_dialog_content = "Como ousam nos atacar sorrateiramente?! Nós não somos alvos fáceis de ninguém! Mate-os, agora!",
  ui_story_5068_50680101_6_dialog_content = "Vamos ver qual de nós acaba morto.",
  ui_story_5068_50680101_7_dialog_content = "(... Como as coisas acabaram assim?)",
  ui_story_5068_50680101_8_dialog_content = "Argh!",
  ui_story_5068_50680101_9_dialog_content = "Que diabos?! Isso é loucura! Pessoal, saquem suas armas! Rápido!!!",
  ui_story_5068_50680101_10_dialog_content = "<color=#e8d9bb>Bam! Bam!</color>",
  ui_story_5068_50680101_11_dialog_content = "Ahhh!",
  ui_story_5068_50680101_12_dialog_content = "Não deixe nenhum deles escapar!!!",
  ui_story_5068_50680101_13_dialog_content = "<color=#e8d9bb><size=45>Bam! Bam! Bam!</size></color>",
  ui_story_5068_50680101_14_dialog_content = "O que... O que exatamente está acontecendo aqui?!",
  ui_story_5068_50680101_15_dialog_content = "Senhora Sheol!!!",
  ui_story_5068_50680101_16_dialog_content = "Você disse que esse trabalho não era perigoso de jeito nenhum—!!",
  ui_story_5068_50680101_17_dialog_content = "<color=#e8d9bb>Um dia atrás</color>",
  ui_story_5068_50680101_18_dialog_content = "Uau, este lugar está tão grandioso agora! Isso é a Guilda Cloudrover para você - ou talvez isso seja tudo graças a você, Senhora Sheol?",
  ui_story_5068_50680101_19_dialog_content = "Faz um tempo que não venho aqui, mas esse lugar expandiu demais. Quase me perdi agora há pouco.",
  ui_story_5068_50680101_20_dialog_content = "Heheh, é realmente tão impressionante? Tenho certeza de que não é nada comparado ao seu magnífico Colosso.",
  ui_story_5068_50680101_21_dialog_content = "Vejo que você veio sozinho hoje... Onde estão as jovens senhoritas que geralmente estão ao seu lado? Não me diga que elas realmente se perderam na Guilda Cloudrover?",
  ui_story_5068_50680101_22_dialog_content = "Bem, o trabalho foi classificado como \"muito baixo risco\", então, mesmo que eu não saiba lutar, eu pensei...",
  ui_story_5068_50680101_23_dialog_content = "A-Ahem! Além disso, não quero ficar incomodando meus amigos com coisas assim! Eles também precisam descansar!",
  ui_story_5068_50680101_24_dialog_content = "Entendi. Suas palavras não me deixam outra opção a não ser reavaliar minha impressão sobre você.",
  ui_story_5068_50680101_25_dialog_content = "Fazer as coisas por conta própria não é necessariamente ruim, mas nunca se esqueça de que sempre haverá momentos em que precisamos contar com os outros.",
  ui_story_5068_50680101_26_dialog_content = "Obrigado pela preocupação, mas não se preocupe. Eu conheço meus próprios limites melhor do que ninguém, e é por isso que sempre sou cuidadoso quando atuo por conta própria.",
  ui_story_5068_50680101_27_dialog_content = "Não tenho motivo para me preocupar se você é quem vai me ajudar. Ainda assim, quero deixar algo bem claro: seu pagamento será determinado pela quantidade de cabeças que você me trouxer.",
  ui_story_5068_50680101_28_dialog_content = "O que?!?",
  ui_story_5068_50680101_29_dialog_content = "Heheh, suas reações são sempre as mais divertidas. Mas chega de brincadeiras por agora, vamos tratar dos negócios de verdade.",
  ui_story_5068_50680101_30_dialog_content = "A verdade é que esse trabalho não pode ser feito sem você, e é por isso que eu não ousaria colocá-lo em perigo.",
  ui_story_5068_50680101_31_dialog_content = "Venha dar uma olhada nisso.",
  ui_story_5068_50680101_32_dialog_content = "O que foi?",
  ui_story_5068_50680101_33_dialog_content = "Apenas leve o seu tempo e analise cuidadosamente.",
  ui_story_5068_50680101_34_dialog_content = "Consigo ver vagamente algo ali dentro. É... uma bola de névoa negra?",
  ui_story_5068_50680101_35_dialog_content = "Não... Não é uma névoa comum. Eu posso sentir algo dentro... Uma presença única.",
  ui_story_5068_50680101_36_option_content = "Aumento de Força!",
  ui_story_5068_50680101_37_dialog_content = "Espere, isso é...?!",
  ui_story_5068_50680101_38_dialog_content = "Costumava haver Lumina dentro dessa névoa!",
  ui_story_5068_50680101_39_dialog_content = "Costumava ser?",
  ui_story_5068_50680101_40_dialog_content = "Sim! Costumava haver Lúmina nesta névoa, mas agora desapareceu completamente... Exceto por alguns traços, que eu só pude sentir usando meus poderes.",
  ui_story_5068_50680101_41_dialog_content = "... Você vê mais alguma coisa?",
  ui_story_5068_50680101_42_dialog_content = "Não.",
  ui_story_5068_50680101_43_dialog_content = "Tem certeza? Eu preciso que você tenha absoluta certeza disso.",
  ui_story_5068_50680101_44_dialog_content = "É por isso que você precisa da minha ajuda? Para investigar essa estranha névoa negra?",
  ui_story_5068_50680101_45_dialog_content = "De fato, mas esta é apenas uma parte do trabalho. O ponto de partida, para ser preciso.",
  ui_story_5068_50680101_46_dialog_content = "Eu sabia que não seria tão simples assim.",
  ui_story_5068_50680101_47_dialog_content = "Nos últimos dias, uma doença altamente perigosa tem se espalhado por Umbraton... ou pelo menos eu acho.",
  ui_story_5068_50680101_48_dialog_content = "Uau, acho que nunca te ouvi soar tão incerto.",
  ui_story_5068_50680101_49_dialog_content = "É mesmo? Em todo caso... \"espalhar\" pode não ser a melhor palavra para descrever isso.",
  ui_story_5068_50680101_50_dialog_content = "Esta doença ocorre em surtos frequentes e concentrados, mas não parece seguir nenhum padrão. As áreas afetadas estão espalhadas aleatoriamente por Umbraton, como gotas de chuva caindo do céu. Isso torna o rastreamento da doença extremamente difícil.",
  ui_story_5068_50680101_51_dialog_content = "Então não é contagioso?",
  ui_story_5068_50680101_52_dialog_content = "Não posso ter certeza, mas minhas descobertas iniciais indicam isso. No entanto, este não é o aspecto mais preocupante da doença.",
  ui_story_5068_50680101_53_dialog_content = "O que seria?",
  ui_story_5068_50680101_54_dialog_content = "Os sintomas.",
  ui_story_5068_50680101_55_dialog_content = "Algum problema?",
  ui_story_5068_50680101_56_dialog_content = "Todo mundo sabe que diferentes doenças têm diferentes sintomas. Por exemplo, uma pessoa sofrendo de um resfriado apresentaria sintomas diferentes de alguém sofrendo de um mal-estar estomacal.",
  ui_story_5068_50680101_57_dialog_content = "Naturalmente, algumas doenças também compartilham sintomas semelhantes, como um resfriado comum e pneumonia. No entanto, este não é o caso com a doença misteriosa de Umbraton.",
  ui_story_5068_50680101_58_dialog_content = "As pessoas que foram afetadas recentemente por isso estão apresentando sintomas diferentes...",
  ui_story_5068_50680101_59_dialog_content = "Alguns sentem uma dor excruciante em todo o corpo, outros perderam completamente a voz e alguns desmaiaram de exaustão devido à mania incontrolável... E esses são apenas alguns dos muitos sintomas inexplicáveis que foram relatados recentemente.",
  ui_story_5068_50680101_60_dialog_content = "Então, não é possível que eles estejam sofrendo de doenças diferentes?",
  ui_story_5068_50680101_61_dialog_content = "Não posso negar essa possibilidade, mas você não acha estranho?",
  ui_story_5068_50680101_62_dialog_content = "Com base em nossas descobertas anteriores, essas pessoas estavam completamente sem sintomas antes de adoecerem. Se fosse apenas uma ou duas pessoas, poderíamos chamar de coincidência.",
  ui_story_5068_50680101_63_dialog_content = "Mas e se isso se aplicasse à grande maioria dos casos? Porque mais de noventa por cento dos pacientes estavam perfeitamente saudáveis um dia e, no dia seguinte, gravemente doentes.",
  ui_story_5068_50680101_64_dialog_content = "Poderia realmente ser apenas uma coincidência?",
  ui_story_5068_50680101_65_dialog_content = "Então você está dizendo...",
  ui_story_5068_50680101_66_dialog_content = "Isso.",
  ui_story_5068_50680101_67_dialog_content = "Desculpe, Senhora Sheol, mas eu não estou realmente entendendo...",
  ui_story_5068_50680101_68_dialog_content = "Esta é a única coisa que todos os pacientes têm em comum.",
  ui_story_5068_50680101_69_dialog_content = "Independentemente dos sintomas ou locais, há uma coisa que une esses casos aparentemente isolados.",
  ui_story_5068_50680101_70_dialog_content = "Você quer dizer... essa névoa preta?",
  ui_story_5068_50680101_71_dialog_content = "Exatamente. A maioria das pessoas em todas as áreas infectadas relatou ver essa névoa negra em algum momento.",
  ui_story_5068_50680101_72_dialog_content = "Não é preciso dizer que meus subordinados se colocaram em perigo mortal para adquirir este espécime.",
  ui_story_5068_50680101_73_dialog_content = "Perigo mortal?!",
  ui_story_5068_50680101_74_dialog_content = "Cuidado... Eu não tenho como saber o que aconteceria se essa névoa vazasse do recipiente.",
  ui_story_5068_50680101_75_dialog_content = "Por favor, não deixe de mencionar detalhes importantes como este na próxima vez que pedir ajuda—",
  ui_story_5068_50680101_76_dialog_content = "De qualquer forma... Você não espera que eu analise a composição da névoa preta, espera?",
  ui_story_5068_50680101_77_dialog_content = "Se for esse o caso, lamento decepcioná-lo, mas minhas habilidades psíquicas têm um limite.",
  ui_story_5068_50680101_78_dialog_content = "Fique tranquilo, analisar a névoa negra não é o motivo pelo qual eu te chamei aqui hoje.",
  ui_story_5068_50680101_79_dialog_content = "Eu simplesmente preciso da sua ajuda para localizar a origem da névoa.",
  ui_story_5068_50680101_80_dialog_content = "Você suspeita... que alguém <color=#FFB400>propositalmente</color> liberou a névoa negra em Umbraton?",
  ui_story_5068_50680101_81_dialog_content = "Ainda não posso dizer com certeza, e é exatamente por isso que preciso da sua ajuda.",
  ui_story_5068_50680101_82_dialog_content = "Esse trabalho não parece muito seguro pra mim...",
  ui_story_5068_50680101_83_dialog_content = "Só preciso que você me relate qualquer descoberta suspeita. Não há necessidade de se aprofundar demais nas coisas, muito menos interagir com os outros.",
  ui_story_5068_50680101_84_dialog_content = "O lendário Caelestite não deveria ter problemas com algo tão simples.",
  ui_story_5068_50680101_85_dialog_content = "Se for esse o caso, eu deveria ser capaz de evitar a maioria das situações perigosas usando meus poderes. Mas ainda assim...",
  ui_story_5068_50680101_86_dialog_content = "Estou bem preparado para compensá-lo generosamente pelos seus problemas. Se o trabalho demorar mais do que o esperado, também pagarei de acordo.",
  ui_story_5068_50680101_87_dialog_content = "Ah, não é isso que quero dizer... Ainda há uma coisa que não entendo.",
  ui_story_5068_50680101_88_dialog_content = "A névoa negra não parece estar afetando a Guilda Cloudrover de maneira perceptível, então por que você está indo tão longe para investigá-la?",
  ui_story_5068_50680101_89_dialog_content = "Ou talvez, sem que eu saiba, você tenha se tornado apaixonado por caridade de repente?",
  ui_story_5068_50680101_90_dialog_content = "... É assim que você me vê? Ainda tem um longo caminho a percorrer, jovem.",
  ui_story_5068_50680101_91_dialog_content = "Fazer negócios é mais do que apenas comprar ou vender. Não estou sendo caridoso; estou apenas pagando os custos necessários para garantir a continuidade dos negócios.",
  ui_story_5068_50680101_92_dialog_content = "Então é isso...",
  ui_story_5068_50680101_93_dialog_content = "Tudo bem, isso cobre tudo. O resto está nas suas mãos agora, PlayerName.",
  ui_story_5068_50680101_94_dialog_content = "<color=#e8d9bb>Depois que você sair...</color>",
  ui_story_5068_50680101_95_dialog_content = "<color=#e8d9bb>Bip Bip-</color>",
  ui_story_5068_50680101_96_dialog_content = "Sou eu.",
  ui_story_5068_50680101_97_dialog_content = "Senhora Sheol! Estarei aí em breve!",
  ui_story_5068_50680101_98_dialog_content = "Tá bom.",
  ui_story_5068_50680201_1_dialog_content = "Acabei em um lugar tão sombrio enquanto perseguia aquela névoa negra... Eu me pergunto se este lugar está dentro da jurisdição de Umbraton. Eu realmente espero que sim.",
  ui_story_5068_50680201_2_dialog_content = "<color=#e8d9bb>Arf... arf...</color>",
  ui_story_5068_50680201_3_dialog_content = "Eita—acabei de sentir um arrepio na espinha. Alguém realmente mora nessas casas? Parece que algo vai pular de repente em mim...",
  ui_story_5068_50680201_4_option_content = "Eu deveria apenas voltar.",
  ui_story_5068_50680201_5_dialog_content = "Não, não, eu já cheguei até aqui. Eu deveria...",
  ui_story_5068_50680201_6_option_content = "Eu deveria continuar!",
  ui_story_5068_50680201_7_dialog_content = "Só preciso descobrir de onde veio a névoa negra e relatar à Senhora Sheol. Não preciso me preocupar com o que acontece depois disso.",
  ui_story_5068_50680201_8_dialog_content = "Além disso, não posso simplesmente desistir no meio do caminho! Preciso me fortalecer!",
  ui_story_5068_50680201_9_option_content = "Aumento de Força",
  ui_story_5068_50680201_10_dialog_content = "Hmm... Parece que estou me aproximando da origem da névoa negra.",
  ui_story_5068_50680201_11_dialog_content = "Eu realmente não esperava que as coisas corressem tão bem. Acho que a Senhora Sheol não estava mentindo sobre o nível de perigo do trabalho, afinal.",
  ui_story_5068_50680201_12_dialog_content = "Socorro! Tem alguém aí? Ajuda!",
  ui_story_5068_50680201_13_dialog_content = "Huh? Estou ouvindo coisas ou alguém acabou de pedir ajuda?",
  ui_story_5068_50680201_14_dialog_content = "Você, você, você! Fiquem longe! Socorro! Alguém, SOCORRO—!",
  ui_story_5068_50680201_15_dialog_content = "Rugido-!",
  ui_story_5068_50680201_16_dialog_content = "Ahhh—!",
  ui_story_5068_50680201_17_dialog_content = "Ah não! Não há tempo—",
  ui_story_5068_50680201_18_dialog_content = "Sai da minha frente!!!",
  ui_story_5068_50680201_19_dialog_content = "Hã?",
  ui_story_5068_50680201_20_dialog_content = "Como os Eclipsitas conseguiram chegar a este lugar?!",
  ui_story_5068_50680202_1_dialog_content = "(Incrível! Ela eliminou todos os Eclipsites antes mesmo que eu tivesse tempo de reagir!)",
  ui_story_5068_50680202_2_dialog_content = "Não deve haver mais Eclipsitas, pelo menos por enquanto. Você está bem?",
  ui_story_5068_50680202_3_dialog_content = "... Estou bem, sem preocupações. Foi por pouco. Obrigado por me salvar, <color=#FFB400>Senhorita Assistente</color>.",
  ui_story_5068_50680202_4_dialog_content = "Não mencione isso. Eu não posso acreditar que os Eclipsitas conseguiram se infiltrar aqui, mesmo ainda sendo parte de Umbraton. Que azar!",
  ui_story_5068_50680202_5_dialog_content = "Como você acabou esbarrando neles?",
  ui_story_5068_50680202_6_dialog_content = "E-Eu não tenho certeza. Eu tinha acabado de terminar o trabalho e, no meu caminho de volta, a neblina apareceu de repente, tudo ficou escuro como breu e então...",
  ui_story_5068_50680202_7_dialog_content = "(... \"Névoa\"? \"Tudo ficou completamente escuro\"? Será que isso é o que eu estou pensando?!)",
  ui_story_5068_50680202_8_dialog_content = "Então, de repente me senti mal e pensei em ir ao <color=#FFB400>médico</color> para verificar, mas...",
  ui_story_5068_50680202_9_dialog_content = "Mas então você encontrou aquelas coisas... Hoje realmente não é o seu dia, né?",
  ui_story_5068_50680202_10_dialog_content = "É assim que é. Pessoas como nós não têm outra opção a não ser viver nessas favelas remotas.",
  ui_story_5068_50680202_11_dialog_content = "Quando algo dá errado aqui... ninguém se importa mesmo. Se eu não tivesse sorte o suficiente para receber sua ajuda, eu provavelmente teria...",
  ui_story_5068_50680202_12_dialog_content = "Ei, ei, pare com as lágrimas! Você está bem, não está? Eu também saí sem nenhum arranhão, então está tudo bem!",
  ui_story_5068_50680202_13_dialog_content = "Ainda consegue ficar de pé?",
  ui_story_5068_50680202_14_dialog_content = "Huh? Parece que minhas pernas estão me falhando...",
  ui_story_5068_50680202_15_dialog_content = "Suspirar...",
  ui_story_5068_50680202_16_dialog_content = "Desculpe, eu sou realmente inútil. Não é um grande problema, mas eu...",
  ui_story_5068_50680202_17_dialog_content = "Não, não foi isso que eu quis dizer. Todo mundo fica assustado quando vê Eclipsitas, então não seja tão duro consigo mesmo.",
  ui_story_5068_50680202_18_dialog_content = "É só que... o <color=#FFB400>médico</color> vai ter mais um paciente hoje.",
  ui_story_5068_50680202_19_dialog_content = "Aqui, me dê sua mão e eu vou te ajudar a levantar!",
  ui_story_5068_50680202_20_dialog_content = "Obrigada, Srta. Assistente. Eu sinto muito mesmo; você me salvou, mas causei tantos problemas a você... Na verdade, eu poderia estar sozinha agora...",
  ui_story_5068_50680202_21_dialog_content = "O quê, você acha que pode sair daqui sozinho? Me poupe!",
  ui_story_5068_50680202_22_dialog_content = "E se aparecerem mais Eclipsitas? O que você faria então?",
  ui_story_5068_50680202_23_dialog_content = "Além disso, acabei de fazer alguns recados para o médico e estava a caminho da clínica. Se você tem energia suficiente para falar um monte de bobagens, então levante-se e venha comigo.",
  ui_story_5068_50680202_24_dialog_content = "Obrigada...",
  ui_story_5068_50680202_25_dialog_content = "... Guarde isso para quando o médico te tratar, agora mexa-se!",
  ui_story_5068_50680202_26_dialog_content = "Espere... Não estou vendo coisas, estou? Aquela senhora...",
  ui_story_5068_50680202_27_dialog_content = "O corpo dela parece estar coberto por algo que se assemelha à névoa negra!",
  ui_story_5068_50680202_28_dialog_content = "Isso é ruim, preciso alcançá-los!",
  ui_story_5068_50680301_1_dialog_content = "Eu sabia. A presença da névoa negra é extremamente intensa por aqui!",
  ui_story_5068_50680301_2_dialog_content = "Esta casa não se destaca de forma alguma, tornando-a um esconderijo perfeito... Eu realmente não consigo acreditar que terminei meu trabalho tão facilmente.",
  ui_story_5068_50680301_3_dialog_content = "Agora tudo que eu preciso fazer é relatar à Senhora Sheol e—",
  ui_story_5068_50680301_4_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5068_50680301_5_dialog_content = "...",
  ui_story_5068_50680301_6_dialog_content = "...",
  ui_story_5068_50680301_7_dialog_content = "Uh... O-Olá?",
  ui_story_5068_50680301_8_dialog_content = "Quem é você? E por que está rondando por aqui?",
  ui_story_5068_50680301_9_dialog_content = "Ah, eu...",
  ui_story_5068_50680301_10_dialog_content = "É porque... Meu estômago... Dói...",
  ui_story_5068_50680301_11_dialog_content = "Ouvi dizer que isso era uma clínica...",
  ui_story_5068_50680301_12_dialog_content = "...",
  ui_story_5068_50680301_13_dialog_content = "Meu estômago... Realmente dói...",
  ui_story_5068_50680301_14_dialog_content = "...",
  ui_story_5068_50680301_15_dialog_content = "(Aquele olhar frio... É como se ela estivesse olhando diretamente para minha alma. Não me diga... Será que ela já viu através de mim?!)",
  ui_story_5068_50680301_16_dialog_content = "... Ah... Bem... Parece que estou no lugar errado... P-Poderia me indicar a direção da clínica?",
  ui_story_5068_50680301_17_dialog_content = "Eu-Eu posso ir encontrá-lo por conta própria...",
  ui_story_5068_50680301_18_dialog_content = "Desculpe incomodar...",
  ui_story_5068_50680301_19_dialog_content = "Segure!",
  ui_story_5068_50680301_20_dialog_content = "(Oh não, acabou a farsa! É melhor eu correr!)",
  ui_story_5068_50680301_21_dialog_content = "Não me ouviu?! Eu disse para segurar!",
  ui_story_5068_50680301_22_dialog_content = "Hã? Ela vai me atacar?!",
  ui_story_5068_50680302_1_dialog_content = "Rosnar—",
  ui_story_5068_50680302_2_dialog_content = "Ufa... Então tinha um Eclipsita atrás de mim o tempo todo? Eu estava bem no começo, mas o ataque dela agora foi assustador o suficiente para me deixar enjoado...",
  ui_story_5068_50680302_3_dialog_content = "\"Bem\"? Eu pensei que você disse que seu estômago estava doendo?",
  ui_story_5068_50680302_4_dialog_content = "—!!!",
  ui_story_5068_50680302_5_dialog_content = "Agora que você mencionou, está começando a doer de novo... O Eclipsita deve ter me assustado tanto que esqueci da dor.",
  ui_story_5068_50680302_6_dialog_content = "Urgh... Meu estômago... Está me matando...",
  ui_story_5068_50680302_7_dialog_content = "Que cara esquisito... Entra aí, eu acho.",
  ui_story_5068_50680302_8_dialog_content = "Você está no lugar certo. Esta é a clínica.",
  ui_story_5068_50680302_9_dialog_content = "... Você deve ficar bem agora. Vá para casa e descanse bastante, e não se esforce demais no trabalho nos próximos dois dias.",
  ui_story_5068_50680302_10_dialog_content = "Obrigado, <color=#FFB400>Doutor</color>. Estou me sentindo muito melhor agora. Mas...",
  ui_story_5068_50680302_11_dialog_content = "Que foi? Você ainda está se sentindo doente?",
  ui_story_5068_50680302_12_dialog_content = "Não, não, não. Suas habilidades médicas são excepcionais e estou me sentindo bem agora. É só... a conta médica...",
  ui_story_5068_50680302_13_dialog_content = "Não se preocupe se não puder cobrir minha taxa agora. Apenas coloque na sua conta e me pague depois, como de costume.",
  ui_story_5068_50680302_14_dialog_content = "Todo mundo se conhece por aqui, então é só voltar quando tiver o dinheiro.",
  ui_story_5068_50680302_15_dialog_content = "Muito obrigado! Eu realmente agradeço! Estou sempre no crédito, e isso é realmente constrangedor...",
  ui_story_5068_50680302_16_dialog_content = "Não se estresse tanto com isso. Nunca é uma boa ideia deixar um problema médico sem tratamento, então venha me ver sempre que precisar, ok?",
  ui_story_5068_50680302_17_dialog_content = "Sim! Ah... Parece que tem um novo paciente. Não vou tomar mais seu tempo, Doutor.",
  ui_story_5068_50680302_18_dialog_content = "(A fonte da névoa negra é... o doutor?)",
  ui_story_5068_50680302_19_dialog_content = "(Parece muito semelhante, mas... algo também parece bem diferente. O que poderia ser?)",
  ui_story_5068_50680302_20_dialog_content = "Olá, qual parece ser o problema?",
  ui_story_5068_50680302_21_dialog_content = "(Se for realmente ela... o que ela poderia estar procurando?)",
  ui_story_5068_50680302_22_dialog_content = "(Ela está fazendo isso de propósito? Será que ela está deixando as pessoas doentes para ter mais pacientes?)",
  ui_story_5068_50680302_23_dialog_content = "(Não, não pode ser isso. Eu acabei de vê-la dispensar as contas médicas daquela garota por enquanto, e não parece ser a primeira vez também.)",
  ui_story_5068_50680302_24_dialog_content = "O médico fez uma pergunta a você, agora pare de encarar ela desse jeito! Deixe-me avisar, se você colocar os olhos em algo que não deveria, nem mesmo ela poderá consertar o que acontecerá com seus olhos!",
  ui_story_5068_50680302_25_dialog_content = "Chega, você está assustando nosso paciente. Agora... O que exatamente há de errado com ele?",
  ui_story_5068_50680302_26_dialog_content = "Ele estava reclamando de dor no estômago mais cedo...",
  ui_story_5068_50680302_27_dialog_content = "Sim... Isso mesmo, é o meu estômago.",
  ui_story_5068_50680302_28_dialog_content = "Isso me lembra, quem te falou sobre a clínica em primeiro lugar?",
  ui_story_5068_50680302_29_dialog_content = "Ah... A-Apenas um estranho amigável. Ele viu quanta dor eu estava sentindo, então me falou sobre uma clínica próxima e como encontrá-la.",
  ui_story_5068_50680302_30_dialog_content = "—!",
  ui_story_5068_50680302_31_dialog_content = "...",
  ui_story_5068_50680302_32_dialog_content = "(Uh, o que está acontecendo? Eu disse algo que não deveria ter dito...?)",
  ui_story_5068_50680302_33_dialog_content = "Uhhhhh... Ugh, ahhhh!",
  ui_story_5068_50680302_34_dialog_content = "Dói! AHHH! Está me matando!",
  ui_story_5068_50680302_35_dialog_content = "Isso é-",
  ui_story_5068_50680302_36_dialog_content = "Ele estava se recuperando até pouco tempo atrás, como isso pode acontecer? Se eu não tratá-lo imediatamente...",
  ui_story_5068_50680302_37_dialog_content = "Estou me sentindo muito mal... Doutor, eu vou morrer? Por favor, eu não quero morrer...",
  ui_story_5068_50680302_38_dialog_content = "Aaaaaaahhh!!!",
  ui_story_5068_50680302_39_dialog_content = "Pare de pensar em coisas assim! Vou te tratar imediatamente, então não tenha medo. Tudo vai ficar bem...",
  ui_story_5068_50680302_40_dialog_content = "(Isso é—)",
  ui_story_5068_50680302_41_dialog_content = "Hã?",
  ui_story_5068_50680302_42_dialog_content = "As coisas entram por um ouvido e saem pelo outro com você, não é? Eu não disse para você manter os olhos só para si?!",
  ui_story_5068_50680302_43_dialog_content = "Desculpe! Eu não queria olhar!",
  ui_story_5068_50680302_44_dialog_content = "(... Se eu não estou enganado, essa médica está usando Lumina para curar seus pacientes. A névoa só sai enquanto ela está tratando deles.)",
  ui_story_5068_50680302_45_dialog_content = "(Mas é diferente da coisa que a Senhora Sheol me deu. A névoa dela está cheia de Lumina, enquanto a amostra da Senhora Sheol não tem nenhuma.)",
  ui_story_5068_50680302_46_dialog_content = "(Será que isso significa que eu estava errado? Não, ainda é cedo demais para afirmar com certeza! Talvez a Lumina esteja presente apenas durante o tratamento dela e depois se esgote quando termina. Depois disso...)",
  ui_story_5068_50680302_47_dialog_content = "(Sem Lumina restante, ele se transforma naquela névoa negra prejudicial! É possível que a médica não saiba como lidar com isso, então ela se desfaz dele em segredo.)",
  ui_story_5068_50680302_48_dialog_content = "(Mas essas são apenas minhas próprias suposições; se estão certas ou não, cabe à Senhora Sheol descobrir. Pode ser que eu esteja completamente errado sobre tudo isso.)",
  ui_story_5068_50680302_49_dialog_content = "Você está bem agora. Tente descansar um pouco e estará curado quando acordar.",
  ui_story_5068_50680302_50_dialog_content = "Emm...",
  ui_story_5068_50680302_51_dialog_content = "Ufa!",
  ui_story_5068_50680302_52_dialog_content = "(Ela parece aliviada ao ver seu paciente em condição estável. Eu não acho que ela esteja fingindo também.)",
  ui_story_5068_50680302_53_dialog_content = "Você já atendeu muitos pacientes hoje, Doutor. Descanse um pouco agora e eu vou \"cuidar\" desse último paciente.",
  ui_story_5068_50680302_54_dialog_content = "Tudo bem, eu posso cuidar dele. Mas... você provavelmente está certo sobre ter muitos pacientes. Já chega de aceitar novos pacientes por hoje, então, por favor, feche a porta.",
  ui_story_5068_50680302_55_dialog_content = "Claro.",
  ui_story_5068_50680302_56_dialog_content = "(?!)",
  ui_story_5068_50680302_57_dialog_content = "Meu assistente me disse que você está sofrendo de dor de estômago, é verdade?",
  ui_story_5068_50680302_58_dialog_content = "É uma doença crônica?",
  ui_story_5068_50680302_59_dialog_content = "Bom...",
  ui_story_5068_50680302_60_dialog_content = "Ou talvez você tenha comido algo que não estava muito limpo?",
  ui_story_5068_50680302_61_dialog_content = "Hã...",
  ui_story_5068_50680302_62_dialog_content = "Hmm... Você não parece disposto a me contar, mas não se preocupe...",
  ui_story_5068_50680302_63_dialog_content = "Tenho muitos medicamentos altamente eficazes para combater a dor de estômago, independentemente da causa.",
  ui_story_5068_50680302_64_dialog_content = "Viu?",
  ui_story_5068_50680302_65_dialog_content = "Com apenas uma única injeção, nenhuma quantidade de dor vai incomodá-lo novamente. Você nem mesmo se lembrará da dor que sentiu antes.",
  ui_story_5068_50680302_66_dialog_content = "Espera aí!",
  ui_story_5068_50680302_67_dialog_content = "Eu... Eu de repente me sinto muito melhor!",
  ui_story_5068_50680302_68_dialog_content = "...",
  ui_story_5068_50680302_69_dialog_content = "D-Desculpe por incomodar, Doutor! Eu definitivamente voltarei para vê-lo se minha dor retornar!",
  ui_story_5068_50680302_70_dialog_content = "Tchau—",
  ui_story_5068_50680302_71_dialog_content = "Agora, quem disse que você poderia sair?",
  ui_story_5068_50680302_72_dialog_content = "(Parece que escapar não é mais uma opção...)",
  ui_story_5068_50680302_73_dialog_content = "Você... não veio aqui procurando tratamento, veio?",
  ui_story_5068_50680401_1_dialog_content = "Você... não veio aqui procurando tratamento, veio?",
  ui_story_5068_50680401_2_dialog_content = "Eu juro que fiz! É só que de repente me sinto muito melhor agora!",
  ui_story_5068_50680401_3_dialog_content = "É loucura, né? Talvez... Talvez tenha sido apenas algo passageiro?",
  ui_story_5068_50680401_4_dialog_content = "Você nos acha idiotas ou algo assim? Chega de fingimento!",
  ui_story_5068_50680401_5_dialog_content = "Você é do tipo que precisa aprender as coisas do jeito difícil, não é? Não me importo em te ensinar uma lição, mas já vou avisando...",
  ui_story_5068_50680401_6_dialog_content = "Isso pode <color=#FFB400>realmente</color> machucar!",
  ui_story_5068_50680401_7_dialog_content = "O-o que você vai fazer comigo?!",
  ui_story_5068_50680401_8_dialog_content = "Tá bom... Já chega, vocês duas.",
  ui_story_5068_50680401_9_dialog_content = "Você não parece ter más intenções, considerando que não tentou nos atacar todo esse tempo... Estou certo?",
  ui_story_5068_50680401_10_dialog_content = "... Está certo!",
  ui_story_5068_50680401_11_dialog_content = "Não isso de novo, Doutor.",
  ui_story_5068_50680401_12_dialog_content = "Você é uma pessoa de coração tão mole. Eu não acho que isso seja ruim, ou então eu não... Enfim, se você continuar confiando nos outros tão facilmente, mais cedo ou mais tarde—",
  ui_story_5068_50680401_13_dialog_content = "Eu sei que você está preocupado comigo, mas eu sei o que estou fazendo. Confie em mim.",
  ui_story_5068_50680401_14_dialog_content = "Além disso, este lugar nos pertence. Enquanto você estiver ao meu lado, não tenho com o que me preocupar.",
  ui_story_5068_50680401_15_dialog_content = "...",
  ui_story_5068_50680401_16_dialog_content = "Agora, você poderia nos dizer por que estava fingindo estar doente?",
  ui_story_5068_50680401_17_dialog_content = "Mas minha barriga realmente doeu agora há pouco...",
  ui_story_5068_50680401_18_dialog_content = "Ah, já chega! Você mesmo estragou seu disfarce há muito tempo, ou ainda não percebeu isso?!",
  ui_story_5068_50680401_19_dialog_content = "Minha atuação é realmente tão ruim assim...?",
  ui_story_5068_50680401_20_dialog_content = "Não foi preciso muito para você admitir... Você deve ser uma pessoa bem honesta.",
  ui_story_5068_50680401_21_dialog_content = "Se sua atuação fosse melhor, estaríamos muito mais desconfiados de você. Para ser honesto, a parte mais reveladora da sua encenação foi uma única declaração.",
  ui_story_5068_50680401_22_dialog_content = "Ah... A-Apenas um estranho amigável. Ele viu quanta dor eu estava sentindo, então me falou sobre uma clínica próxima e como encontrá-la.",
  ui_story_5068_50680401_23_dialog_content = "Minha clínica não é muito grande e é bem escondida. Além disso, temos uma regra muito especial aqui—",
  ui_story_5068_50680401_24_dialog_content = "Qualquer pessoa que visite a clínica deve ser pessoalmente apresentada por alguém que conhecemos.",
  ui_story_5068_50680401_25_dialog_content = "Todos os meus pacientes sabem que não aceito pacientes com históricos desconhecidos, o que significa que eles nunca me recomendariam a alguém desconhecido para eles.",
  ui_story_5068_50680401_26_dialog_content = "Assim que você disse isso, nós dois sabíamos que você estava mentindo para nós.",
  ui_story_5068_50680401_27_dialog_content = "Entendo...",
  ui_story_5068_50680401_28_dialog_content = "Meu assistente e eu precisamos manter um perfil discreto por motivos que não podemos revelar.",
  ui_story_5068_50680401_29_dialog_content = "Eu já te disse muito mais do que era necessário... Então, você se importaria de nos dizer por que está aqui?",
  ui_story_5068_50680401_30_dialog_content = "A verdade é... Fui encarregado de investigar uma estranha doença que vem se espalhando por Umbraton recentemente. E minha investigação me trouxe a este lugar.",
  ui_story_5068_50680401_31_dialog_content = "No começo, eu pensei que tinha uma pista importante, mas no final acho que peguei a pessoa errada...",
  ui_story_5068_50680401_32_dialog_content = "...",
  ui_story_5068_50680401_33_dialog_content = "...",
  ui_story_5068_50680401_34_dialog_content = "Ainda inventando histórias, hein?!",
  ui_story_5068_50680401_35_dialog_content = "N-Não, eu juro que é a verdade!",
  ui_story_5068_50680401_36_dialog_content = "Não há necessidade de continuar perdendo seu tempo com esse cara, Doutor. Além disso, ele viu seu método de tratamento agora há pouco.",
  ui_story_5068_50680401_37_dialog_content = "É... É mesmo? Nesse caso, tudo que posso dizer é que me desculpe.",
  ui_story_5068_50680401_38_dialog_content = "(Oh não, parece que estou em apuros agora... O que eles vão fazer comigo?!)",
  ui_story_5068_50680401_39_option_content = "Aumento de Força!",
  ui_story_5068_50680401_40_dialog_content = "(Desculpe mesmo, mas para manter <color=#FFB400>Eleanor</color> e eu mesmo em segurança, não tenho outra escolha senão fazer isso.)",
  ui_story_5068_50680401_41_dialog_content = "(Você deve ter assumido este trabalho recentemente, certo? Se sim, essa injeção fará você esquecer tudo o que aconteceu no último mês...)",
  ui_story_5068_50680401_42_dialog_content = "(Uma vez que você esteja dormindo, eu vou pedir ao Eleanor para te levar a um lugar seguro. Você não deveria ter entrado nesta clínica.)",
  ui_story_5068_50680401_43_dialog_content = "(<color=#FFB400>Rebecca</color> ainda é uma pessoa muito gentil.)",
  ui_story_5068_50680401_44_dialog_content = "(Eu sabia que esse cara não prestava desde o momento em que ele entrou e começou a falar bobagens. Se dependesse de mim, eu o teria jogado fora com o resto do lixo sem pensar duas vezes.)",
  ui_story_5068_50680401_45_dialog_content = "(Essa Rebecca senhora não parece querer me machucar, e sua assistente realmente a ouve.)",
  ui_story_5068_50680401_46_dialog_content = "(Se eu nunca tivesse me intrometido neles, provavelmente ela não precisaria fazer isso comigo. Mas talvez... talvez eu ainda tenha uma chance de conquistar a confiança dela?)",
  ui_story_5068_50680401_47_dialog_content = "(Eu só tenho uma chance nisso!)",
  ui_story_5068_50680401_48_dialog_content = "Espere! Você tem tratado muitos pacientes com sintomas misteriosos ultimamente?",
  ui_story_5068_50680401_49_dialog_content = "Pare de tentar enrolar para ganhar tempo!",
  ui_story_5068_50680401_50_dialog_content = "... Tudo bem, deixe-o falar.",
  ui_story_5068_50680401_51_dialog_content = "Bem, eu não sei por que vocês dois estão sendo tão secretivos, mas posso ver que você realmente tem o interesse de seus pacientes no coração, Doutor.",
  ui_story_5068_50680401_52_dialog_content = "Talvez possamos trabalhar juntos para encontrar a raiz dessas doenças estranhas?",
  ui_story_5068_50680401_53_dialog_content = "Hmm... Você mencionou que seu trabalho envolve investigar uma doença estranha, certo? Você fez algum outro progresso?",
  ui_story_5068_50680401_54_dialog_content = "Só isso.",
  ui_story_5068_50680401_X54_dialog_content = "Você já viu algo assim antes, Dr. Rebecca? Como médico, você deve saber muito mais sobre isso do que eu.",
  ui_story_5068_50680401_55_dialog_content = "—!!!",
  ui_story_5068_50680401_56_dialog_content = "O-O que você está fazendo com isso?! Onde você achou?!",
  ui_story_5068_50680401_57_dialog_content = "Espere! Como você sabe o nome de Rebecca?!",
  ui_story_5068_50680401_58_dialog_content = "(Ah! Deixei escapar!)",
  ui_story_5068_50680401_59_dialog_content = "Desembucha antes que eu te force a fazê-lo!",
  ui_story_5068_50680401_60_dialog_content = "Espere, a menos que... você esteja com os <color=#FFB400>Lobos Negros</color>, não é?!",
  ui_story_5068_50680401_61_dialog_content = "Os Lobos Negros? Quem são eles?",
  ui_story_5068_50680401_62_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5068_50680401_63_dialog_content = "Alguém disse que isso era uma clínica? Um lugar assim?",
  ui_story_5068_50680401_64_dialog_content = "Está um pouco degradado, mas olhe para as coisas dentro; isso é realmente uma clínica!",
  ui_story_5068_50680401_65_dialog_content = "Essas máscaras... Será que os Lobos Negros estão realmente por trás de tudo isso?",
  ui_story_5068_50680401_66_dialog_content = "Não tente nada engraçado! Seus amigos aqui já nos contaram tudo!",
  ui_story_5068_50680401_67_dialog_content = "Espera, para! Eu não conheço essas pessoas! Não estamos trabalhando juntos, eu juro!",
  ui_story_5068_50680401_68_dialog_content = "Tsk. Doutor! Doutor, saia rápido! Quem é o médico aqui?",
  ui_story_5068_50680401_69_dialog_content = "Ouvi dizer que o médico daqui pode tratar doenças causadas pela névoa negra. Apareça aqui agora!",
  ui_story_5068_50680401_70_dialog_content = "Não tem médico aqui! Mas se você está procurando um motivo para ver um, eu ficarei feliz em te dar!",
  ui_story_5068_50680401_71_dialog_content = "Se perder, escória!",
  ui_story_5068_50680401_72_dialog_content = "Ai!",
  ui_story_5068_50680401_73_dialog_content = "Por que essa louca morde todo mundo que vê?! Ainda bem que reagi rápido!",
  ui_story_5068_50680401_74_dialog_content = "Como ousam nos atacar sorrateiramente?! Nós não somos alvos fáceis de ninguém! Mate-os, agora!",
  ui_story_5068_50680401_75_dialog_content = "Vamos ver qual de nós acaba morto.",
  ui_story_5068_50680401_76_dialog_content = "Argh!",
  ui_story_5068_50680401_77_dialog_content = "Que diabos?! Isso é loucura! Pessoal, saquem suas armas! Rápido!!!",
  ui_story_5068_50680401_78_dialog_content = "<color=#e8d9bb>Bam! Bam!</color>",
  ui_story_5068_50680401_79_dialog_content = "Ahhh!",
  ui_story_5068_50680401_80_dialog_content = "Não deixe nenhum deles escapar!!!",
  ui_story_5068_50680401_81_dialog_content = "<size=45><color=#e8d9bb>Bam! Bam! Bam!</color></size>",
  ui_story_5068_50680401_82_dialog_content = "(O que está acontecendo aqui... Como as coisas acabaram assim?!)",
  ui_story_5068_50680401_83_dialog_content = "(A porta está completamente bloqueada. Eu não conseguiria escapar mesmo que quisesse...)",
  ui_story_5068_50680401_84_dialog_content = "<color=#e8d9bb>Bip Bip-</color>",
  ui_story_5068_50680401_85_dialog_content = "Vamos lá! Atenda, Senhora Sheol!!",
  ui_story_5068_50680502_1_dialog_content = "Bando de idiotas! Esse cara está com vocês, não está? Se vocês não querem que nada aconteça com ele—",
  ui_story_5068_50680502_2_dialog_content = "Eu te disse que não estamos trabalhando juntos...",
  ui_story_5068_50680502_3_dialog_content = "Essa mulher está maluca? Ela escolheu um cara aleatório e afirmou que ele era um dos nossos Lobos Negros. Alguém de vocês conhece esse cara?",
  ui_story_5068_50680502_4_dialog_content = "Não. Você conhece ele?",
  ui_story_5068_50680502_5_dialog_content = "Que coincidência; também não o conheço.",
  ui_story_5068_50680502_6_dialog_content = "Hahahahaha!",
  ui_story_5068_50680502_7_dialog_content = "É isso que eu venho te dizendo o tempo todo! Por que você não acredita em mim?!",
  ui_story_5068_50680502_8_dialog_content = "Manter-me como refém não fará bem a nenhum de vocês, então poderiam, por favor, tirar a faca do meu pescoço? Eu posso realmente me machucar...",
  ui_story_5068_50680502_9_dialog_content = "Cala a boca! Mesmo que você não esteja junto com esses caras, ainda é lixo aos meus olhos!",
  ui_story_5068_50680502_10_dialog_content = "Apenas deixe-o ir. Não queremos que nenhum espectador inocente se machuque.",
  ui_story_5068_50680502_11_dialog_content = "Inocente é a última palavra que eu usaria para descrever esse cara.",
  ui_story_5068_50680502_12_dialog_content = "Mas se até o médico está dizendo isso... Então considere este o seu dia de sorte.",
  ui_story_5068_50680502_13_dialog_content = "Deixe-me deixar isso bem claro! Qualquer um que mexer com os Lobos Negros não vai acabar bem!",
  ui_story_5068_50680502_14_dialog_content = "Sabe, nós estávamos pensando em tomar conta deste bairro pacificamente. Mas agora, parece que pisotear tudo é uma opção melhor!",
  ui_story_5068_50680502_15_dialog_content = "...",
  ui_story_5068_50680502_16_dialog_content = "Então, o que exatamente vocês idiotas estão fazendo aqui?",
  ui_story_5068_50680502_17_dialog_content = "Espere um minuto! Eu te conheço! Você é—",
  ui_story_5068_50680502_18_dialog_content = "Você é Eleanor!",
  ui_story_5068_50680502_19_dialog_content = "...",
  ui_story_5068_50680502_20_dialog_content = "Isso mesmo! Eu me lembro agora! Eu te conheço!",
  ui_story_5068_50680502_21_dialog_content = "Huh? El... o quê? Não me lembra nada.",
  ui_story_5068_50680502_22_dialog_content = "Eleanor! Quero dizer—",
  ui_story_5068_50680502_23_dialog_content = "É...",
  ui_story_5068_50680502_24_dialog_content = "Eu realmente sinto muito...",
  ui_story_5068_50680502_25_dialog_content = "Mas se isso continuar, você só vai causar mais problemas para nós... Você não me deixou escolha...",
  ui_story_5068_50680502_26_dialog_content = "Uhh...",
  ui_story_5068_50680502_27_dialog_content = "Apenas relaxe, prometo que não vai doer muito...",
  ui_story_5068_50680502_28_dialog_content = "O quê!? O que você fez com ele?!",
  ui_story_5068_50680502_29_dialog_content = "Não se preocupe, não tenho intenção de tirar a vida de ninguém.",
  ui_story_5068_50680502_30_dialog_content = "Como você pode ver, eu acabei de deixá-lo inconsciente.",
  ui_story_5068_50680502_31_dialog_content = "Essa, essa mulher, ela é louca... Recuar... Mova-se, mova-se!",
  ui_story_5068_50680502_32_dialog_content = "Volte e relate aos chefes! Deixe os superiores—",
  ui_story_5068_50680502_33_dialog_content = "Eca!!!",
  ui_story_5068_50680502_34_dialog_content = "Desculpe, mas não posso deixar nenhum de vocês escapar.",
  ui_story_5068_50680502_35_dialog_content = "Se ao menos um de vocês conseguir sair com as memórias intactas... Isso vai me causar ainda mais problemas.",
  ui_story_5068_50680502_36_dialog_content = "Desculpe, senhorita Rebecca. Aquele cara deve ter me reconhecido dos meus dias de andanças...",
  ui_story_5068_50680502_37_dialog_content = "Tudo bem, Eleanor, eu sabia que esse dia chegaria mais cedo ou mais tarde. Era apenas uma questão de tempo.",
  ui_story_5068_50680502_38_dialog_content = "(Tudo o que precisou foi de um único ataque...)",
  ui_story_5068_50680502_39_dialog_content = "(Parece que Rebecca não estava lutando com toda a sua força contra aqueles Lobos Negros.)",
  ui_story_5068_50680502_40_dialog_content = "(Ela parece tão frágil, mas na verdade é muito poderosa... Não acho que seja apenas uma médica comum.)",
  ui_story_5068_50680502_41_dialog_content = "Quanto a você, fique tranquilo que não tenho intenção de fazer o mesmo com você... Pelo menos não agora.",
  ui_story_5068_50680502_42_dialog_content = "Você também não precisa se preocupar com essas pessoas.",
  ui_story_5068_50680502_43_dialog_content = "Você se lembra da injeção que eu ia te dar mais cedo? Para dizer a verdade, na verdade não era remédio.",
  ui_story_5068_50680502_44_dialog_content = "Senhorita Rebecca? Você não acha que está contando demais para ele?",
  ui_story_5068_50680502_45_dialog_content = "Não se preocupe. Eu sei o que estou fazendo.",
  ui_story_5068_50680502_46_dialog_content = "O soro na injeção não é remédio, mas <color=#FFB400>veneno</color>... O mesmo tipo que acabei de administrar nessas pessoas.",
  ui_story_5068_50680502_47_dialog_content = "Veneno?!",
  ui_story_5068_50680502_48_dialog_content = "Sim, veneno... Mas não é letal.",
  ui_story_5068_50680502_49_dialog_content = "Essas pessoas... estão apenas inconscientes, nada mais.",
  ui_story_5068_50680502_50_dialog_content = "Quando esses vilões acordarem, eles esquecerão quem são e o que estavam fazendo!",
  ui_story_5068_50680502_51_dialog_content = "Desculpe, garotinho... Nós te assustamos agora há pouco?",
  ui_story_5068_50680502_52_dialog_content = "Não estou com medo nenhum!",
  ui_story_5068_50680502_53_dialog_content = "Então, você está se sentindo melhor?",
  ui_story_5068_50680502_54_dialog_content = "Estou me sentindo muito melhor agora! Obrigado, Doutor!",
  ui_story_5068_50680502_55_dialog_content = "Bom... Você parece estar perfeitamente bem, o que significa que pode ir para casa agora.",
  ui_story_5068_50680502_56_dialog_content = "A clínica não está muito segura no momento, então, por favor, avise a todos para ficarem longe por enquanto.",
  ui_story_5068_50680502_57_dialog_content = "E lembre-se de manter tudo o que aconteceu aqui em segredo, entendeu?",
  ui_story_5068_50680502_58_dialog_content = "Entendido! Considere isso feito!",
  ui_story_5068_50680502_59_dialog_content = "Então vou voltar por enquanto! Adeus, Doutor! Adeus, Senhorita Assistente!",
  ui_story_5068_50680502_60_dialog_content = "Eleanor... Você poderia, por favor, se livrar dessas pessoas agora?",
  ui_story_5068_50680502_61_dialog_content = "—!",
  ui_story_5068_50680502_62_dialog_content = "Por favor, não entenda mal. Eu só quero que ela os leve para um lugar seguro e longe daqui.",
  ui_story_5068_50680502_63_dialog_content = "Por que você está contando tudo isso para ele, Srta. Rebecca? Apenas nocauteie-o para que eu possa me livrar dele junto com os outros!",
  ui_story_5068_50680502_64_dialog_content = "Eu mudei de ideia.",
  ui_story_5068_50680502_65_dialog_content = "... Não entendo.",
  ui_story_5068_50680502_66_dialog_content = "Não percebi isso antes... Talvez seja porque estivemos escondidos nesta pequena clínica no último ano?",
  ui_story_5068_50680502_67_dialog_content = "As favelas e esta clínica... Eles nos deram proteção, mas também limitaram um pouco nossa perspectiva.",
  ui_story_5068_50680502_68_dialog_content = "Eu não fazia ideia de que ainda havia Celestitas no mundo.",
  ui_story_5068_50680502_69_dialog_content = "...",
  ui_story_5068_50680502_70_dialog_content = "Celestitas? O que são esses?",
  ui_story_5068_50680502_71_dialog_content = "Você não percebeu? Tipo, algo que não parecia tão normal quanto o habitual durante a luta?",
  ui_story_5068_50680502_72_dialog_content = "Acho que realmente pareceu um pouco diferente...",
  ui_story_5068_50680502_73_dialog_content = "Parecia que... eu podia ver diferentes padrões de Lumina ao meu redor! Isso tornou a luta ainda mais suave do que o normal!",
  ui_story_5068_50680502_74_dialog_content = "Então não foi apenas minha imaginação, pelo visto.",
  ui_story_5068_50680502_75_dialog_content = "E se minha intuição estiver correta... Isso faz de você um Celestita, não é?",
  ui_story_5068_50680502_76_dialog_content = "Apenas os lendários Celestitas são capazes de usar essa técnica especial para nos ajudar na batalha.",
  ui_story_5068_50680502_77_dialog_content = "Você mencionou meu nome sem querer mais cedo, o que provavelmente aprendeu através dessas mesmas habilidades, certo?",
  ui_story_5068_50680502_78_dialog_content = "Você parece saber muito sobre os Celestitas.",
  ui_story_5068_50680502_79_dialog_content = "Apenas pelo que li em livros sobre o passado, eu tinha a impressão de que os Celestitas eram todos...",
  ui_story_5068_50680502_80_dialog_content = "Desculpe, é só que... nunca esperei conhecer um Celestita assim.",
  ui_story_5068_50680502_81_dialog_content = "Bem, você está certo. Meu nome é PlayerName e eu realmente sou um celestita. Quem exatamente são vocês dois?",
  ui_story_5068_50680502_82_dialog_content = "Apenas uma <color=#FFB400>doutora sem nome</color> e seu <color=#FFB400>assistente sem nome</color>. Isso é tudo que você precisa saber!",
  ui_story_5068_50680502_83_dialog_content = "Eleanor... PlayerName teve a gentileza de se apresentar, então devemos fazer o mesmo por ele.",
  ui_story_5068_50680502_84_dialog_content = "Senhorita Rebecca?!",
  ui_story_5068_50680502_85_dialog_content = "Esse é o meu nome—Rebecca Svanedona. E este é Eleanor.",
  ui_story_5068_50680502_86_dialog_content = "Por certos motivos... Tivemos que manter nossos nomes em segredo.",
  ui_story_5068_50680502_87_dialog_content = "E mesmo assim você estava disposto a compartilhá-los comigo.",
  ui_story_5068_50680502_88_dialog_content = "Isso é porque acredito que você não quer nos fazer mal.",
  ui_story_5068_50680502_89_dialog_content = "Nos livros que li, os Celestitas sempre foram descritos como uma raça gentil e pacífica...",
  ui_story_5068_50680502_90_dialog_content = "Além disso... Você não parece ter habilidades de combate, então, se você agisse contra nós, eu não teria problemas em subjugar você. Não é verdade?",
  ui_story_5068_50680502_91_dialog_content = "(Embora o tom dela seja gentil, não há um pingo de compaixão em suas palavras... Mesmo depois de me dizer o nome dela, ela continua tão distante quanto antes.)",
  ui_story_5068_50680502_92_dialog_content = "Então esse cara é ainda mais fraco do que parece? Bom, isso é uma coisa a menos para se preocupar.",
  ui_story_5068_50680502_93_dialog_content = "Vou me livrar da escória que está espalhada pelo nosso chão.",
  ui_story_5068_50680502_94_dialog_content = "Julgando pelo que disseram antes, este lugar não é mais seguro. É possível...",
  ui_story_5068_50680502_95_dialog_content = "Que teremos que deixar este lugar para trás... E todo o Umbraton também.",
  ui_story_5068_50680502_96_dialog_content = "Se as coisas chegarem a esse ponto—",
  ui_story_5068_50680502_97_dialog_content = "Não se preocupe... Eu vou fazer planos para o pior cenário.",
  ui_story_5068_50680502_98_dialog_content = "Além disso, você deve ficar na sala escondida até eu voltar.",
  ui_story_5068_50680502_99_dialog_content = "Não deixe ninguém entrar enquanto eu estiver fora.",
  ui_story_5068_50680601_1_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5068_50680601_2_dialog_content = "... Tá certo, esse deve ser o último deles.",
  ui_story_5068_50680601_3_dialog_content = "Silvo...",
  ui_story_5068_50680601_4_dialog_content = "Hum? Já está acordando, hein?",
  ui_story_5068_50680601_5_dialog_content = "Você... o que está fazendo?!",
  ui_story_5068_50680601_6_dialog_content = "Huh? Onde é esse lixão? Pessoal, acordem!",
  ui_story_5068_50680601_7_dialog_content = "... Hum?",
  ui_story_5068_50680601_8_dialog_content = "O que... o que está acontecendo?!",
  ui_story_5068_50680601_9_dialog_content = "Todos, acordem! Ei, ei! Acordem agora!",
  ui_story_5068_50680601_10_dialog_content = "Minha cabeça... está girando. Por que não consigo me lembrar de nada?",
  ui_story_5068_50680601_11_dialog_content = "... Este aqui na nossa frente deve saber de algo.",
  ui_story_5068_50680601_12_dialog_content = "Fale alto! Por que você estava se esgueirando ao nosso redor agora há pouco? Quem está por trás disso?!",
  ui_story_5068_50680601_13_dialog_content = "Hã? Como eles estão todos acordados tão cedo?",
  ui_story_5068_50680601_14_dialog_content = "A senhorita Rebecca deu a eles uma dosagem menor para evitar efeitos colaterais duradouros? Como eu sempre digo, ela é uma pessoa muito bondosa...",
  ui_story_5068_50680601_15_dialog_content = "O que ela estava murmurando para si mesma sozinha?",
  ui_story_5068_50680601_16_dialog_content = "Quem se importa? Vamos buscá-la!",
  ui_story_5068_50680601_17_dialog_content = "Hmph. Odeio decepcioná-los, mas não sou nem de longe tão gentil quanto o médico!",
  ui_story_5068_50680602_1_dialog_content = "—?!",
  ui_story_5068_50680602_2_dialog_content = "Não sou médico, então me perdoe se eu errar a dosagem.",
  ui_story_5068_50680602_3_dialog_content = "Mas eu prometo, essa injeção fará você esquecer tudo e ter uma vida nova. Bons sonhos, seu lixo.",
  ui_story_5068_50680602_4_dialog_content = "Hã?!",
  ui_story_5068_50680602_5_dialog_content = "Você é o último.",
  ui_story_5068_50680602_6_dialog_content = "Por favor... Por favor, apenas me deixe ir...",
  ui_story_5068_50680602_7_dialog_content = "Huh? Espere um segundo...",
  ui_story_5068_50680602_8_dialog_content = "Eleanor?",
  ui_story_5068_50680602_9_dialog_content = "Eleanor, é você, né?! Não, não me dê essa injeção! Eu sei que vou morrer se você fizer isso!",
  ui_story_5068_50680602_10_dialog_content = "Isso não cabe a você.",
  ui_story_5068_50680602_11_dialog_content = "Não! Eu imploro, Eleanor! Pelos velhos tempos, por favor, poupe seu amigo!",
  ui_story_5068_50680602_12_dialog_content = "Cuidei tanto de você em <color=#FFB400>todos esses anos</color>!",
  ui_story_5068_50680602_13_dialog_content = "Você conhece as regras, então apenas responda algumas das minhas perguntas.",
  ui_story_5068_50680602_14_dialog_content = "Claro! O que você quiser! Só prometa me deixar ir, e eu te contarei tudo o que sei!",
  ui_story_5068_50680602_15_dialog_content = "O que você foi enviado para fazer?",
  ui_story_5068_50680602_16_dialog_content = "... O que eu fui enviado para fazer hoje? Eu...",
  ui_story_5068_50680602_17_dialog_content = "Não consegue se lembrar, né?",
  ui_story_5068_50680602_18_dialog_content = "N-Não é isso! Só me dê um minuto! Não, trinta segundos!",
  ui_story_5068_50680602_19_dialog_content = "... Eu lembro! Finalmente me lembro agora!",
  ui_story_5068_50680602_20_dialog_content = "Nós... Fomos enviados aqui para testar um recém-desenvolvido...",
  ui_story_5068_50680602_21_dialog_content = "...",
  ui_story_5068_50680602_22_dialog_content = "Se você não puder me contar, não vou forçar você a fazê-lo.",
  ui_story_5068_50680602_23_dialog_content = "A <color=#FFB400>névoa negra</color>.",
  ui_story_5068_50680602_24_dialog_content = "Nós... Fomos enviados aqui para testar os efeitos de uma névoa negra recém-desenvolvida, e também...",
  ui_story_5068_50680602_25_dialog_content = "Para encontrar um médico que possa tratar seus efeitos - Aparentemente, o <color=#FFB400>Diretor</color> está extremamente interessado nessa pessoa...",
  ui_story_5068_50680602_26_dialog_content = "Um teste? De um novo tipo de névoa negra?!",
  ui_story_5068_50680602_27_dialog_content = "Sim... E foi quando ouvimos falar de um médico suspeito no subsolo. Na verdade, tenho quase certeza de que estávamos a caminho de procurar esse médico... Então, o que estamos fazendo aqui?",
  ui_story_5068_50680602_28_dialog_content = "Espere!",
  ui_story_5068_50680602_29_dialog_content = "O que você também está fazendo aqui? E o que você está—",
  ui_story_5068_50680602_30_dialog_content = "Desculpe... Irmão.",
  ui_story_5068_50680602_31_dialog_content = "Você está se lembrando de um pouco demais agora.",
  ui_story_5068_50680602_32_dialog_content = "<color=#e8d9bb>Ruído, farfalhar...</color>",
  ui_story_5068_50680602_33_dialog_content = "Piu—Piu—",
  ui_story_5068_50680701_1_dialog_content = "<color=#e8d9bb>Tique-taque... Tique-taque...</color>",
  ui_story_5068_50680701_2_dialog_content = "Um momento por favor.",
  ui_story_5068_50680701_3_dialog_content = "<color=#e8d9bb>Clique, clique.</color>",
  ui_story_5068_50680701_4_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5068_50680701_5_dialog_content = "Lá. Se você quer saber mais sobre a névoa negra, por favor, venha comigo.",
  ui_story_5068_50680701_6_dialog_content = "Mas primeiro, preciso pedir... Que você mantenha tudo o que ver e ouvir nesta sala escondida em segredo.",
  ui_story_5068_50680701_7_dialog_content = "Claro, eu prometo.",
  ui_story_5068_50680701_8_dialog_content = "Por favor, cuidado onde pisa...",
  ui_story_5068_50680701_9_dialog_content = "Estamos aqui.",
  ui_story_5068_50680701_10_dialog_content = "—!!",
  ui_story_5068_50680701_11_dialog_content = "Lá... Tem tantos potes e garrafas aqui!",
  ui_story_5068_50680701_12_dialog_content = "Eu venho acumulando-os há muito tempo sem perceber. Antes que eu percebesse, o quarto estava cheio de espécimes.",
  ui_story_5068_50680701_13_dialog_content = "Não me diga que isso é tudo o que...",
  ui_story_5068_50680701_14_dialog_content = "Alguns são e outros não. Há até mesmo vários deles que têm efeitos completamente diferentes.",
  ui_story_5068_50680701_15_dialog_content = "Esses potes e garrafas contêm os frutos da minha pesquisa. Ao usar meu poder em <color=#FFB400>diferentes tipos de Lúmina</color>, posso produzir diversos tipos de soros com uma ampla variedade de efeitos.",
  ui_story_5068_50680701_16_dialog_content = "<color=#FFB400>Diferentes tipos de Lúmina</color>?",
  ui_story_5068_50680701_17_dialog_content = "Como você provavelmente já sabe, esta clínica funciona nas favelas - nem todos que vêm aqui podem pagar pelo tratamento ou medicamentos com dinheiro.",
  ui_story_5068_50680701_18_dialog_content = "Então, para aqueles pacientes com Lúmina forte e carteiras vazias, ofereço a opção de pagar pelos meus serviços com sua Lúmina.",
  ui_story_5068_50680701_19_dialog_content = "Você está familiarizado com esse tipo de situação? Quando se trata de pesquisa, não há nada mais importante do que ter espécimes e materiais suficientes à disposição.",
  ui_story_5068_50680701_20_dialog_content = "Não se preocupe, nunca forcei ninguém a cumprir com o meu trabalho. Por favor, confie em mim quando digo que toda essa Lumina foi fornecida voluntariamente pelos meus pacientes ou seus familiares.",
  ui_story_5068_50680701_21_dialog_content = "A Lúmina que eu reúno cada vez é também muito pequena e não resultará em efeitos negativos a longo prazo para os Aurorianos.",
  ui_story_5068_50680701_22_dialog_content = "Mas exatamente o que você está pesquisando que exigiria tanta Lúmina?",
  ui_story_5068_50680701_23_dialog_content = "Se é para fazer e vender mais coisas como esse veneno de perda de memória... Não posso deixar de me preocupar com isso.",
  ui_story_5068_50680701_24_dialog_content = "Peço desculpas por causar essa impressão. Você deve pensar... Que estou tramando algo terrível, certo?",
  ui_story_5068_50680701_25_dialog_content = "Tudo que eu sei é que você é um bom médico quando está com seus pacientes. Isso é inegável.",
  ui_story_5068_50680701_26_dialog_content = "Mas ainda estou curioso para saber qual é o objetivo da sua \"pesquisa.\"",
  ui_story_5068_50680701_27_dialog_content = "O objetivo da minha pesquisa...",
  ui_story_5068_50680701_28_dialog_content = "Como um celestita, você deve ser capaz de usar seus poderes especiais para ler minha mente, certo?",
  ui_story_5068_50680701_29_dialog_content = "Meus \"poderes especiais\" são, na verdade, uma espécie de habilidade psíquica. Só posso usá-los em situações perigosas.",
  ui_story_5068_50680701_30_dialog_content = "Habilidades psíquicas... Entendi. Elas podem ser usadas para outras coisas? Como imobilizar outras pessoas, por exemplo?",
  ui_story_5068_50680701_31_dialog_content = "Nada disso, não. Além de me deixar pilotar minha Colossus e dirigir os outros na batalha... Eles realmente não podem ser usados para mais nada.",
  ui_story_5068_50680701_32_dialog_content = "Seu Colossus? Sim, eu me lembro de algo sobre os Celestitas terem veículos com esse nome.",
  ui_story_5068_50680701_33_dialog_content = "Soroz não é apenas um veículo; é o meu amigo mais próximo e importante.",
  ui_story_5068_50680701_34_dialog_content = "\"Soroz\"? É assim que você chama sua Colossus? Que nome impressionante...",
  ui_story_5068_50680701_35_dialog_content = "Se você tiver tempo, adoraria apresentá-lo ao Soroz algum dia. Muitos dos nossos amigos gostam de embarcar para passar o tempo juntos.",
  ui_story_5068_50680701_36_dialog_content = "Ah... Talvez algum dia, com certeza...",
  ui_story_5068_50680701_37_dialog_content = "Obrigado por compartilhar tanto sobre você e os Celestitas... Acho que também devo compartilhar alguns segredos sobre mim.",
  ui_story_5068_50680701_38_dialog_content = "A névoa negra, para começar.",
  ui_story_5068_50680701_39_dialog_content = "Esta névoa negra... é minha família.",
  ui_story_5068_50680701_40_dialog_content = "... Sua família?",
  ui_story_5068_50680701_41_dialog_content = "Você quer dizer que usou o Lumina da sua família para fazer isso...?",
  ui_story_5068_50680701_42_dialog_content = "Não. Esta névoa negra é o método único de... Existir da <color=#FFB400>Família Svanedona</color>.",
  ui_story_5068_50680701_43_dialog_content = "Talvez você não saiba, mas até um ano atrás, a Família Svanedona era uma das mais proeminentes e ricas famílias de toda Umbraton.",
  ui_story_5068_50680701_44_dialog_content = "Esta família possui uma habilidade única que é passada de geração em geração: o poder de criar <color=#FFB400>seruns</color> curativos com sua Lumina.",
  ui_story_5068_50680701_45_dialog_content = "E acontece que eu sou um dos membros deles.",
  ui_story_5068_50680701_46_dialog_content = "Além de criar soros medicinais, também sou capaz de produzir um tipo altamente perigoso de <color=#FFB400>veneno</color>. Se é um gene recessivo ou um presente divino, ninguém sabe, embora minha família prefira muito mais a última explicação.",
  ui_story_5068_50680701_47_dialog_content = "No passado, eu era completamente ignorante sobre os usos e implicações desse veneno. Afinal, eu sempre preferi usar meus poderes para curar pessoas, mas então...",
  ui_story_5068_50680701_48_dialog_content = "...",
  ui_story_5068_50680701_49_dialog_content = "O que tá acontecendo? Onde estou?",
  ui_story_5068_50680701_50_dialog_content = "Rebecca? Rebecca! Você está aí?",
  ui_story_5068_50680701_51_dialog_content = "Estou aqui, PlayerName. Por favor, não tenha medo, estou apenas usando a névoa para recriar minhas lembranças daquele dia...",
  ui_story_5068_50680701_52_dialog_content = "Olhar...",
  ui_story_5068_50680701_53_dialog_content = "A pessoa no chão é meu tio Albert. Ele gostava especialmente de me abraçar quando eu era pequeno, mas eu não suportava a sensação espinhosa de sua barba.",
  ui_story_5068_50680701_54_dialog_content = "A garotinha sentada ali é minha prima Jessica. Ela sempre foi uma menina fofa; lembro que ela carregava uma boneca para onde quer que fosse, e era tão fofa quanto ela. Minha irmã mais velha Isa também a adorava.",
  ui_story_5068_50680701_55_dialog_content = "Isa... minha irmã também adorava me comprar coisas caras o tempo todo, mesmo que eu não tivesse utilidade para a maioria delas. Naquele dia, eu nem tive a chance de ver o rosto dela pela última vez.",
  ui_story_5068_50680701_56_dialog_content = "E lá está... minha mãe Lillian. Sinto muito a falta dela. Os ensopados que ela fazia, o calor de seu abraço e o sorriso no rosto dela quando me dizia que me amava.",
  ui_story_5068_50680701_57_dialog_content = "Mas eles não fazem mais parte deste mundo agora.",
  ui_story_5068_50680701_58_dialog_content = "Se Eleanor não tivesse me resgatado naquela época, eu provavelmente teria me transformado na névoa negra, assim como eles.",
  ui_story_5068_50680701_59_dialog_content = "A névoa negra... Mas você não disse que era a forma única deles existirem?",
  ui_story_5068_50680701_60_dialog_content = "É verdade. Quando um membro da Família Svanedona morre e o Lumina deixa completamente o corpo deles, o soro de cura que costumavam produzir se deteriora em uma substância venenosa.",
  ui_story_5068_50680701_61_dialog_content = "E se esse veneno entrar em contato com um fogo quente o suficiente...",
  ui_story_5068_50680701_62_dialog_content = "Torna-se uma névoa negra que pode bloquear o céu.",
  ui_story_5068_50680701_63_dialog_content = "Às vezes, me pergunto por que nasci com a habilidade de produzir esse veneno...",
  ui_story_5068_50680701_64_dialog_content = "Quando minha família foi atacada pelos <color=#FFB400>Lobos Negros</color>, percebi dolorosamente o quão completamente impotente eu estava para protegê-los.",
  ui_story_5068_50680701_65_dialog_content = "Foi o momento mais baixo e sem esperança da minha vida.",
  ui_story_5068_50680701_66_dialog_content = "Então, vocês dois estiveram se escondendo dos Lobos Negros todo esse tempo, hein...",
  ui_story_5068_50680701_67_dialog_content = "Permita-me responder à sua pergunta anterior. No último ano, estive pesquisando como utilizar adequadamente meu veneno...",
  ui_story_5068_50680701_68_dialog_content = "Eu tenho apenas um objetivo: proteger a pessoa que me importa.",
  ui_story_5068_50680701_69_dialog_content = "E isso seria Eleanor, certo?",
  ui_story_5068_50680701_70_dialog_content = "Sim... Ela é tudo que me restou agora.",
  ui_story_5068_50680701_71_dialog_content = "Mas a névoa negra em sua mão...",
  ui_story_5068_50680701_72_dialog_content = "Tenho certeza de que foi criado por um membro da Família Svanedona que teve um fim prematuro. Além disso, foi criado recentemente!",
  ui_story_5068_50680701_73_dialog_content = "Em outras palavras...",
  ui_story_5068_50680701_74_dialog_content = "Tenho uma proposta para você, PlayerName...",
  ui_story_5068_50680701_75_dialog_content = "Eu sei o que você está pensando. É possível que alguns dos seus familiares tenham sobrevivido ao ataque do ano passado e que os Lobos Negros estejam explorando-os neste exato momento...",
  ui_story_5068_50680701_76_dialog_content = "Parece que minha investigação está progredindo, afinal.",
  ui_story_5068_50680701_77_dialog_content = "Não se preocupe, mesmo que meu trabalho seja investigar a névoa negra, com certeza vou ajudá-lo a procurar sinais de sua família.",
  ui_story_5068_50680701_78_dialog_content = "Obrigado, PlayerName...",
  ui_story_5068_50680801_1_dialog_content = "Piu—Piu—",
  ui_story_5068_50680801_2_dialog_content = "Procurem cuidadosamente a área onde a Equipe B realizou seus experimentos! O desaparecimento deles não foi um acidente!",
  ui_story_5068_50680801_3_dialog_content = "Não deixem pedra sobre pedra! Ninguém descansa até encontrarmos os culpados por trás disso!",
  ui_story_5068_50680801_4_dialog_content = "Sim, Diretor!",
  ui_story_5068_50680801_5_dialog_content = "Foi você, Rebecca? Mesmo depois de um ano inteiro... Você ainda está rondando Umbraton? Você realmente acha que pode me desprezar assim? Ou talvez...",
  ui_story_5068_50680801_6_dialog_content = "Hum?",
  ui_story_5068_50680801_7_dialog_content = "<color=#e8d9bb>Tique-taque... Tique-taque...</color>",
  ui_story_5068_50680801_8_dialog_content = "Três... não, cinco deles... Talvez até mais. Eles continuam me seguindo e não consigo me livrar deles.",
  ui_story_5068_50680801_9_dialog_content = "Parece que um daqueles palhaços conseguiu chamar reforços, afinal...",
  ui_story_5068_50680801_10_dialog_content = "Vamos lá, covardes! Saiam e lutem!",
  ui_story_5068_50680802_1_dialog_content = "Espere... Pare! Parem todos vocês!",
  ui_story_5068_50680802_2_dialog_content = "Acha que vou parar só porque você pediu?!",
  ui_story_5068_50680802_3_dialog_content = "Abra seus olhos, Eleanor! Sou eu—Isa! Não me diga que você esqueceu de mim?!",
  ui_story_5068_50680802_4_dialog_content = "Isa...?",
  ui_story_5068_50680802_5_dialog_content = "Você está... Você ainda está vivo?!",
  ui_story_5068_50680802_6_dialog_content = "Não por muito tempo, se você não parar de me atacar!",
  ui_story_5068_50680802_7_dialog_content = "Eleanor? O que está acontecendo aqui fora? Eu ouvi uma briga, então eu...",
  ui_story_5068_50680802_8_dialog_content = "—!!!",
  ui_story_5068_50680802_9_dialog_content = "É... É realmente você...",
  ui_story_5068_50680802_10_dialog_content = "Rebecca—!",
  ui_story_5068_50680802_11_dialog_content = "Eu estive procurando por você em todos os lugares durante o último ano!",
  ui_story_5068_50680802_12_dialog_content = "Graças a Deus... Graças a Deus você ainda está vivo! Estou tão feliz por finalmente ter te encontrado!!!",
  ui_story_5068_50680802_13_dialog_content = "... <color=#FFB400>Isa</color>?!",
  ui_story_5068_50680802_14_dialog_content = "Não... Eu devo estar sonhando...",
  ui_story_5068_50680802_15_dialog_content = "Isso não é um sonho, Rebecca!",
  ui_story_5068_50680802_16_dialog_content = "Mas achei que também tinha te perdido naquele dia...",
  ui_story_5068_50680802_17_dialog_content = "Bem, como você pode ver, estou perfeitamente bem! Você, por outro lado... Passou por muita coisa, não é?",
  ui_story_5068_50680802_18_dialog_content = "(Isa? Não é a irmã mais velha de Rebecca? Será que isso realmente é uma coincidência?)",
  ui_story_5068_50680802_19_dialog_content = "(Também... Estou imaginando coisas? Parece que o veneno ao redor de Rebecca está enfraquecendo conforme Isa se aproxima dela.)",
  ui_story_5068_50680802_20_dialog_content = "E você deve ser PlayerName, certo?",
  ui_story_5068_50680802_21_dialog_content = "Graças às informações que você forneceu, finalmente consegui encontrar minha irmã aqui... Eu realmente não sei como agradecer o suficiente!",
  ui_story_5068_50680802_22_dialog_content = "Mas eu não me lembro de ter te dado—Espera, será que foi a Senhora Sheol?!",
  ui_story_5068_50680802_23_dialog_content = "Sim! A Senhora Sheol recebeu suas mensagens e gravações de mais cedo, mas ela não conseguiu entrar em contato com você desde então.",
  ui_story_5068_50680802_24_dialog_content = "Uau, sem brincadeira! Meu terminal está cheio de mensagens dela! Eu devo ter ficado tão envolvido no caos que esqueci de verificar...",
  ui_story_5068_50680802_25_dialog_content = "Então você é o assistente que a Senhora Sheol enviou aqui?!",
  ui_story_5068_50680802_26_dialog_content = "Isso mesmo! Atualmente estou trabalhando para a Senhora Sheol e a Guilda Cloudrover.",
  ui_story_5068_50680802_27_dialog_content = "Há algum tempo, descobri que os Lobos Negros estavam procurando uma garota que pudesse tratar os efeitos venenosos da névoa negra...",
  ui_story_5068_50680802_28_dialog_content = "Isso me levou a acreditar que minha irmã ainda estava viva em algum lugar. Foi então que pedi à Senhora Sheol para me ajudar a ficar de olho.",
  ui_story_5068_50680802_29_dialog_content = "Eu estive ajudando ela a cobrar dívidas nos últimos dias, mas quando ouvi falar sobre a névoa negra, voltei o mais rápido que pude.",
  ui_story_5068_50680802_30_dialog_content = "Assim que cheguei, a Senhora Sheol me disse que alguém chamado PlayerName havia entrado em contato com um médico clandestino, e que provavelmente era minha irmã Rebecca. Mesmo que não fosse ela, a pessoa ainda estava intimamente ligada à Família Svanedona...",
  ui_story_5068_50680802_31_dialog_content = "Então, reuni minha equipe e corri para cá imediatamente!",
  ui_story_5068_50680802_32_dialog_content = "Sua... equipe?",
  ui_story_5068_50680802_33_dialog_content = "Heehee! A Guilda Cloudrover foi legal o suficiente para—",
  ui_story_5068_50680802_34_dialog_content = "Devemos continuar essa conversa dentro da clínica. Não está seguro aqui fora no momento, e também tem a questão do que aconteceu mais cedo...",
  ui_story_5068_50680802_35_dialog_content = "Não é seguro, você diz? E o que aconteceu antes?",
  ui_story_5068_50680802_36_dialog_content = "Está tudo bem agora, Isa. Vamos entrar.",
  ui_story_5068_50680802_37_dialog_content = "Huh? OK, claro!",
  ui_story_5068_50680802_38_dialog_content = "Ei! Fiquem de olho na clínica e na área ao redor! Ninguém entra a menos que eu dê a ordem!",
  ui_story_5068_50680802_39_dialog_content = "Entendido!",
  ui_story_5068_50680901_1_dialog_content = "... Se eu não tivesse agido como um pirralho teimoso com nosso pai naquele dia, eu nunca teria saído de casa furioso.",
  ui_story_5068_50680901_2_dialog_content = "Mas no momento em que saí, nossa casa foi atacada...",
  ui_story_5068_50680901_3_dialog_content = "Eu realmente não sabia o que fazer por conta própria. Tentei entrar em contato com alguns dos nossos antigos conhecidos, mas acabei sendo traído por alguns traidores podres!",
  ui_story_5068_50680901_4_dialog_content = "Esgotado...?!",
  ui_story_5068_50680901_5_dialog_content = "Olhando para trás, foi minha culpa por ser tão descuidado. Quando finalmente percebi, já estava cercado... Eles me fizeram passar por um inferno depois disso, mas felizmente a Senhora Sheol apareceu um dia.",
  ui_story_5068_50680901_6_dialog_content = "Ela é uma pessoa incrível! Não só ela me salvou, como também me deu um emprego... É por isso que quero retribuir trabalhando o mais duro possível para ela!",
  ui_story_5068_50680901_7_dialog_content = "Eu não fazia ideia que você passou por tanto em apenas um ano...",
  ui_story_5068_50680901_8_dialog_content = "Hahaha! Isso tudo é passado, então não se preocupe com isso. Além disso, não disse que estou perfeitamente bem agora?",
  ui_story_5068_50680901_9_dialog_content = "Para mim, é como—Como eu deveria dizer? Ah, certo! Eu tive que criar minha própria sorte!",
  ui_story_5068_50680901_10_dialog_content = "Mas vamos falar de você, Rebecca! Como você veio parar em um lugar como este?",
  ui_story_5068_50680901_11_dialog_content = "Tudo está completamente degradado por aqui. O que a irmãzinha mais fofa do mundo está fazendo correndo pelas favelas?",
  ui_story_5068_50680901_12_dialog_content = "Eleanor! Como Rebecca empregada, você não deveria cuidar melhor dela?",
  ui_story_5068_50680901_13_dialog_content = "Eu—claro que tenho cuidado bem dela! Como eu poderia fazer diferente?!",
  ui_story_5068_50680901_14_dialog_content = "Rebecca é a pessoa mais importante do mundo para mim. Mesmo que isso me custasse a vida, eu faria—",
  ui_story_5068_50680901_15_dialog_content = "Então por que você não encontrou um lugar melhor para ela morar? Este lugar é absolutamente inaceitável!",
  ui_story_5068_50680901_16_dialog_content = "Isa, eu sei que você está apenas preocupado comigo... Mas por favor, não culpe ela.",
  ui_story_5068_50680901_17_dialog_content = "Ela não é mais uma serva da Família Svanedona e... nós também não somos mais filhas de nobres.",
  ui_story_5068_50680901_18_dialog_content = "Se não fosse por Eleanor, eu teria... De qualquer forma, ela me resgatou e tem feito o seu melhor para me manter seguro dos Lobos Negros no último ano.",
  ui_story_5068_50680901_19_dialog_content = "Não foi fácil para ela encontrar esta clínica \"degradada\" e reformá-la também.",
  ui_story_5068_50680901_20_dialog_content = "Pode não ser o mais sofisticado, mas nos protege dos elementos.",
  ui_story_5068_50680901_21_dialog_content = "Vivemos como médica e assistente aqui, e valorizo a nova vida que construímos juntos.",
  ui_story_5068_50680901_22_dialog_content = "Senhorita Rebecca...",
  ui_story_5068_50680901_23_dialog_content = "Além disso, viver aqui não é tão ruim assim.",
  ui_story_5068_50680901_24_dialog_content = "Quando não temos tantos pacientes, cultivamos flores e fazemos artesanato como costumávamos fazer...",
  ui_story_5068_50680901_25_dialog_content = "Viu? Eleanor fez esses brincos para mim com suas próprias mãos!",
  ui_story_5068_50680901_26_dialog_content = "Eles parecem bem comuns... Quer dizer, se fosse eu, teria feito um conjunto ainda mais bonito para você.",
  ui_story_5068_50680901_27_dialog_content = "Eu costumava comprar coisas para você o tempo todo. Se alguém sabe o que mais combina com você, sou eu!",
  ui_story_5068_50680901_28_dialog_content = "...",
  ui_story_5068_50680901_29_dialog_content = "Sim, sim, eu sei. Você realmente tem um olho para esse tipo de coisa.",
  ui_story_5068_50680901_30_dialog_content = "*Tosse*",
  ui_story_5068_50680901_31_dialog_content = "Hum? Você tem algo a dizer, PlayerName?",
  ui_story_5068_50680901_32_dialog_content = "N-Não mesmo! É só que parece que Rebecca é a irmã mais velha aqui...",
  ui_story_5068_50680901_33_dialog_content = "Huh? Por que todo mundo continua dizendo isso? Até mesmo nossos familiares costumavam...",
  ui_story_5068_50680901_34_dialog_content = "... Isa, você acha que algum dos nossos familiares ainda está por aí?",
  ui_story_5068_50680901_35_dialog_content = "Ia te fazer exatamente a mesma pergunta. Parece que nenhum de nós sabe, né?",
  ui_story_5068_50680901_36_dialog_content = "A Senhora Sheol me deu uma identidade falsa, então os Lobos Negros não conseguiram me encontrar... Eu só ouvi falar deles tentando caçar você, não qualquer outro membro da nossa família.",
  ui_story_5068_50680901_37_dialog_content = "Eu tinha a impressão de que todos foram perdidos no ataque do ano passado. Foi só quando PlayerName me mostrou aquela garrafa de névoa negra que percebi que alguém da nossa família foi apenas recentemente...",
  ui_story_5068_50680901_38_dialog_content = "Ainda assim... isso também significa que pode haver outros Svanedonas por aí, certo?",
  ui_story_5068_50680901_39_dialog_content = "Também é possível que eles estejam fugindo dos Lobos Negros, assim como nós. Alguns deles podem ter sido capturados e explorados também...",
  ui_story_5068_50680901_40_dialog_content = "Não se preocupe, Rebecca. Prometo que vou te ajudar a encontrá-los, não importa o quê!",
  ui_story_5068_50680901_41_dialog_content = "Antes de continuarmos nossa investigação, sugiro que mudemos de local o mais rápido possível. A clínica não é mais segura.",
  ui_story_5068_50680901_42_dialog_content = "Os Lobos Negros... Mesmo depois de atacar nossa família inteira há um ano, eles ainda não desistiram da caçada? O que eles poderiam querer de nós?",
  ui_story_5068_50680901_43_dialog_content = "Se a Senhora Sheol não tivesse me impedido, eu já teria ido acertar as contas com eles!",
  ui_story_5068_50680901_44_dialog_content = "Eu posso não conhecer essa \"Senhora Sheol\" que você menciona, mas acho que ela tem a ideia certa. Enfrentar os Lobos Negros sozinho é incrivelmente perigoso.",
  ui_story_5068_50680901_45_dialog_content = "Mas e agora? Eu tenho você, além de muitas pessoas na Guilda Cloudrover para me ajudar. Mais cedo ou mais tarde, vou cobrar a dívida que os Lobos Negros devem à Família Svanedona!",
  ui_story_5068_50680901_46_dialog_content = "Isso mesmo! Se você precisa de um novo lugar para se esconder dos Lobos Negros, por que não vir à Guilda Cloudrover comigo?",
  ui_story_5068_50680901_47_dialog_content = "Acho que é uma ótima ideia!",
  ui_story_5068_50680901_48_dialog_content = "A Senhora Sheol é quem me contratou para isso, e todos aqui estão intimamente ligados à névoa negra. Tenho certeza de que ela lhe oferecerá a melhor proteção que a guilda pode comprar.",
  ui_story_5068_50680901_49_dialog_content = "Mas...",
  ui_story_5068_50680901_50_dialog_content = "Hum? Tem algo em mente, Rebecca?",
  ui_story_5068_50680901_51_dialog_content = "Tenho certeza de que ela está preocupada em envolver a Senhora Sheol e a Guilda Cloudrover nos nossos problemas... Assim como você, Isa.",
  ui_story_5068_50680901_52_dialog_content = "O quê? Mas somos família! Eu nunca ficaria chateado com algo assim, e nem a Senhora Sheol! Ela é uma boa pessoa, tenho certeza de que ela não se importará!",
  ui_story_5068_50680901_53_dialog_content = "Não importa o quão cruéis os Lobos Negros possam ser, eles seriam loucos em fazer inimigos com a Guilda Cloudrover. Quando chegar a hora certa, podemos usar o poder da guilda para esmagá-los e vingar nossa família!",
  ui_story_5068_50680901_54_dialog_content = "Vingança... Nunca é tão simples. Eu só quero continuar vivendo em paz... com você e Eleanor ao meu lado.",
  ui_story_5068_50680901_55_dialog_content = "Eu sei, Rebecca, mas o mundo não é tão simples assim.",
  ui_story_5068_50680901_56_dialog_content = "Eu sei que você não quer machucar ninguém, mas isso não importa para eles! As pessoas encontrarão todos os tipos de razões para te machucar!",
  ui_story_5068_50680901_57_dialog_content = "Eu nunca quis mostrar a crueldade do nosso mundo, mas independentemente do que queremos, precisamos encarar a realidade de frente agora!",
  ui_story_5068_50680901_58_dialog_content = "É totalmente irrazoável, certo?",
  ui_story_5068_50680901_59_dialog_content = "Mas é assim que as coisas funcionam: os fortes devoram os fracos, e apenas os mais aptos sobrevivem. Se não tomarmos a iniciativa—",
  ui_story_5068_50680901_60_dialog_content = "Já chega! Não precisa mais ficar importunando ela com isso!",
  ui_story_5068_50680901_61_dialog_content = "Ela sempre foi uma pessoa gentil e amável. Enquanto ela continuar assim, eu cuidarei de tudo o mais sozinho!",
  ui_story_5068_50680901_62_dialog_content = "Você? Mas há um limite para o que você pode fazer! Algumas coisas precisam ser decididas por ela e mais ninguém! Você não pode esperar estar ao lado dela a cada minuto de todos os dias!",
  ui_story_5068_50680901_63_dialog_content = "Eu posso e eu vou! É exatamente isso que venho fazendo no último ano!",
  ui_story_5068_50680901_64_dialog_content = "Acalmem-se, pessoal! Agora não é hora de discutir...",
  ui_story_5068_50680901_65_dialog_content = "Ainda acho que Isa tem a ideia certa, Rebecca—Se você está preocupado com sua segurança, a Guilda Cloudrover é um bom lugar para montar acampamento.",
  ui_story_5068_50680901_66_dialog_content = "O que você acha, Eleanor?",
  ui_story_5068_50680901_67_dialog_content = "Vou concordar com o que você decidir, Senhorita Rebecca.",
  ui_story_5068_50680901_68_dialog_content = "Entendi... Não há tempo para hesitar, então parece que teremos que contar com a Guilda Cloudrover por enquanto.",
  ui_story_5068_50680901_69_dialog_content = "Bom! Agora que decidimos, vamos nos mexer imediatamente!",
  ui_story_5068_50680901_70_dialog_content = "Só preciso de um momento para juntar algumas coisas. Me dê uma mão, Eleanor.",
  ui_story_5068_50680901_71_dialog_content = "Sim, senhorita Rebecca.",
  ui_story_5068_50680901_72_dialog_content = "Então deixe-me—",
  ui_story_5068_50680901_73_dialog_content = "Eleanor já é ajuda suficiente, Isa. Ela conhece as coisas de que preciso, então por favor... Apenas fique à vontade por enquanto.",
  ui_story_5068_50680901_74_dialog_content = "Eleanor de novo... Hmph. O que ela poderia saber sobre Rebecca que sua própria irmã não sabe?!",
  ui_story_5068_50680901_75_dialog_content = "Ei! Quem é você e qual é o seu propósito aqui?!",
  ui_story_5068_50680901_76_dialog_content = "Huh? O que é esse tumulto repentino lá fora?",
  ui_story_5068_50680901_77_dialog_content = "Ei! O que está acontecendo lá fora?!",
  ui_story_5068_50680901_78_dialog_content = "*Tossindo* Urgh—É... É a névoa negra! Alguém a soltou no ar!",
  ui_story_5068_50680901_79_dialog_content = "Isso é ruim! Vamos conferir!",
  ui_story_5068_50680901_80_dialog_content = "Quem poderia ter liberado tanta névoa negra por aqui...",
  ui_story_5068_50680901_81_dialog_content = "Foi os Lobos Negros?!",
  ui_story_5068_50680901_82_dialog_content = "*Tossindo* É horrível...!",
  ui_story_5068_50680901_83_dialog_content = "Aqui, pessoal! Rápido!",
  ui_story_5068_50680901_84_dialog_content = "Rebecca? Quando você saiu?",
  ui_story_5068_50680901_85_dialog_content = "Ouvi uma agitação do lado de fora agora há pouco. Aqui, este soro deve diminuir bastante os efeitos da névoa negra. Pessoal, venham aqui e peguem um pouco para vocês!",
  ui_story_5068_50680901_86_dialog_content = "Alvo avistado!",
  ui_story_5068_50680901_87_dialog_content = "...!!",
  ui_story_5068_50680901_88_dialog_content = "Suma daqui! Eu não vou deixar nenhum de vocês encostar um dedo na Srta. Rebecca!",
  ui_story_5068_50680902_1_dialog_content = "Estão todos bem?",
  ui_story_5068_50680902_2_dialog_content = "Graças ao seu soro, me sinto muito melhor.",
  ui_story_5068_50680902_3_dialog_content = "Esta névoa negra... Parece muito mais potente do que a coisa que a Senhora Sheol me deu antes.",
  ui_story_5068_50680902_4_dialog_content = "...",
  ui_story_5068_50680902_5_dialog_content = "Isso não é bom, Isa!",
  ui_story_5068_50680902_6_dialog_content = "O que aconteceu agora?",
  ui_story_5068_50680902_7_dialog_content = "Olhe lá fora... Um bando de moradores de favela está começando a cercar este lugar!",
  ui_story_5068_50680902_8_dialog_content = "Moradores de favela? Mas o que eles estão fazendo aqui?",
  ui_story_5068_50680902_9_dialog_content = "Ah não...!",
  ui_story_5068_50680902_10_dialog_content = "Espere! Você não tem permissão para entrar!",
  ui_story_5068_50680902_11_dialog_content = "Quem... Quem são vocês? Cadê o médico? *tosse, tosse* Precisamos da ajuda dela... Toda essa névoa negra apareceu de repente, e todos...",
  ui_story_5068_50680902_12_dialog_content = "Urgh... Dói tanto... Cadê o médico...?",
  ui_story_5068_50680902_13_dialog_content = "Há tantas pessoas, e algumas delas já desmaiaram...",
  ui_story_5068_50680902_14_dialog_content = "Eleanor! Pessoal! Eu... Eu preciso da ajuda de vocês!",
  ui_story_5068_50680902_15_dialog_content = "Sim, senhorita Rebecca!",
  ui_story_5068_50680902_16_dialog_content = "Hã?",
  ui_story_5068_50680902_17_dialog_content = "Pare de reclamar! Você a ouviu, agora vá ajudar!",
  ui_story_5068_50680902_18_dialog_content = "Por favor, não entrem em pânico, pessoal! Mantenham distância uns dos outros e evitem pisar nos desacordados!",
  ui_story_5068_50680902_19_dialog_content = "... Todos eles vieram em busca de ajuda. Eu me recuso a abandonar qualquer um deles!",
  ui_story_5068_50680902_20_dialog_content = "Rebecca? O que você...",
  ui_story_5068_50680902_21_dialog_content = "Não há tempo, então vou ter que tratar todos eles de uma vez...",
  ui_story_5068_50680902_22_dialog_content = "Espere, você vai tratar tantas pessoas ao mesmo tempo? Seu corpo aguenta isso?!",
  ui_story_5068_50680902_23_dialog_content = "Haaaa—!!",
  ui_story_5068_50680902_24_dialog_content = "*Tosse* Está ficando... mais fácil de respirar...",
  ui_story_5068_50680902_25_dialog_content = "O médico... ela nos salvou novamente...",
  ui_story_5068_50680902_26_dialog_content = "...",
  ui_story_5068_50680902_27_dialog_content = "Senhorita Rebecca!!!",
  ui_story_5068_50680902_28_dialog_content = "Ei! Pare de me assustar assim! Rebecca?!",
  ui_story_5068_50680902_29_dialog_content = "Está... Está todo mundo bem agora? Estou um pouco... sem fôlego. Eleanor, vá verificar como eles estão por mim...",
  ui_story_5068_50680902_30_dialog_content = "Rebecca, eu—",
  ui_story_5068_50680902_31_dialog_content = "Vai!",
  ui_story_5068_50680902_32_dialog_content = "...",
  ui_story_5068_50680902_33_dialog_content = "Ei! Rebecca? Rebecca?!",
  ui_story_5068_50680902_34_dialog_content = "Pare de sacudi-la! Ela consumiu muita Lumina, então ela está extremamente delicada agora. Precisamos encontrar um lugar seguro para ela se recuperar!",
  ui_story_5068_50680902_35_dialog_content = "Eu... estou bem. Eleanor, e os outros—",
  ui_story_5068_50680902_36_dialog_content = "Eles estão bem por enquanto, Srta. Rebecca. Graças ao seu tratamento, tudo que eles precisam é de um pouco de descanso para se recuperarem completamente.",
  ui_story_5068_50680902_37_dialog_content = "... É mesmo? Que alívio.",
  ui_story_5068_50680902_38_dialog_content = "Os Lobos Negros perderam completamente a cabeça?! Como eles puderam fazer algo tão horrível?!",
  ui_story_5068_50680902_39_dialog_content = "Eles podem ter outro objetivo em mente.",
  ui_story_5068_50680902_40_dialog_content = "... Eles estão tentando forçar a Srta. Rebecca a sair do esconderijo!",
  ui_story_5068_50680902_41_dialog_content = "Ah... Este lugar está completamente comprometido agora!",
  ui_story_5068_50680902_42_dialog_content = "Então, vamos para a Guilda Cloudrover. Não consigo pensar em um lugar mais seguro para irmos agora.",
  ui_story_5068_50680902_43_dialog_content = "Entendi! Eu vou carregar Rebecca!",
  ui_story_5068_50680902_44_dialog_content = "Não, deixe isso comigo.",
  ui_story_5068_50680902_45_dialog_content = "Você... tudo bem! Mas tome cuidado!",
  ui_story_5068_50680902_46_dialog_content = "...",
  ui_story_5068_50680902_47_dialog_content = "Quanto a vocês, fiquem aqui e mantenham as coisas sob controle. Assim que essas pessoas se recuperarem, mandem-nas para casa imediatamente!",
  ui_story_5068_50680902_48_dialog_content = "Sim!",
  ui_story_5068_50681001_1_dialog_content = "Diretor...",
  ui_story_5068_50681001_2_dialog_content = "Confirmamos a presença de Rebecca na área onde a Equipe B desapareceu, mas...",
  ui_story_5068_50681001_3_dialog_content = "Eu te ensinei melhor do que enrolar, agora desembucha.",
  ui_story_5068_50681001_4_dialog_content = "É só que os ataques de veneno dela tornam difícil nos aproximarmos... Muito menos capturá-la viva.",
  ui_story_5068_50681001_5_dialog_content = "... Ela realmente tem um dom se aprendeu a controlar seu veneno em apenas um ano.",
  ui_story_5068_50681001_6_dialog_content = "Mas você ainda é muito mais forte do que ela, Diretor. Afinal, você criou uma névoa negra que <color=#FFB400>combate especificamente o veneno dela</color>!",
  ui_story_5068_50681001_7_dialog_content = "Isso não é da sua preocupação.",
  ui_story_5068_50681001_8_dialog_content = "F-Perdoe-me, Diretor! Eu vou ficar de boca fechada...",
  ui_story_5068_50681001_9_dialog_content = "Então, onde está Rebecca agora?",
  ui_story_5068_50681001_10_dialog_content = "Encontramos ela na Clínica Subterrânea, mas ela tinha alguns aliados ao seu lado. Eles estão levando-a para a Guilda Cloudrover neste exato momento.",
  ui_story_5068_50681001_11_dialog_content = "Mas o fato é que ainda não é o momento certo para enfrentá-los.",
  ui_story_5068_50681001_12_dialog_content = "A Guilda Cloudrover?",
  ui_story_5068_50681001_13_dialog_content = "Isso realmente torna as coisas mais difíceis, mas ainda temos outras opções.",
  ui_story_5068_50681001_14_dialog_content = "Tudo bem, devemos estar seguros agora que chegamos à Guilda Cloudrover.",
  ui_story_5068_50681001_15_dialog_content = "Você está se sentindo melhor agora, Rebecca?",
  ui_story_5068_50681001_16_dialog_content = "Sim... Desculpe por incomodar todos agora há pouco.",
  ui_story_5068_50681001_17_dialog_content = "Não precisa ser tão educado comigo! A Guilda Cloudrover está em nosso território, então apenas relaxe enquanto cuidamos do resto!",
  ui_story_5068_50681001_18_dialog_content = "Parece que ainda faltam alguns suprimentos nesta sala, mas não se preocupe! Eu vou comprar para você!",
  ui_story_5068_50681001_19_dialog_content = "Espere, Isa... É muito perigoso sair agora, não é?",
  ui_story_5068_50681001_20_dialog_content = "Como eu disse, esta é a Guilda Cloudrover, então os Lobos Negros teriam que ser muito estúpidos para arrumar uma briga conosco aqui. Não se preocupe, eu voltarei antes que você perceba!",
  ui_story_5068_50681001_21_dialog_content = "PlayerName... Você não parece tão bem... Está se sentindo bem?",
  ui_story_5068_50681001_22_dialog_content = "Estou bem. Só que esse trabalho acabou sendo muito mais complicado do que eu pensava...",
  ui_story_5068_50681001_23_dialog_content = "Mas não se preocupe, só preciso de um tempo para pensar. Vá em frente e descanse um pouco.",
  ui_story_5068_50681001_24_dialog_content = "Desculpe por... causar tantos problemas para você...",
  ui_story_5068_50681001_25_dialog_content = "Hum...",
  ui_story_5068_50681001_26_dialog_content = "...!!!",
  ui_story_5068_50681001_27_dialog_content = "Eleanor... Depressa...",
  ui_story_5068_50681001_28_dialog_content = "PlayerName, você pode sair agora.",
  ui_story_5068_50681001_29_dialog_content = "Hã? M-Mas Rebecca é...",
  ui_story_5068_50681001_30_dialog_content = "Eu disse para sair! Rebecca precisa descansar agora mesmo!",
  ui_story_5068_50681001_31_dialog_content = "Caramba, quase esqueci de perguntar! Ei, Rebecca, o que exatamente você precisa que eu faça—",
  ui_story_5068_50681001_32_dialog_content = "Err...",
  ui_story_5068_50681001_33_dialog_content = "R-Rebecca...? O que-O que está acontecendo aqui?!",
  ui_story_5068_50681001_34_dialog_content = "Isa... Por favor... Não olhe...",
  ui_story_5068_50681001_35_dialog_content = "Err...",
  ui_story_5068_50681001_36_dialog_content = "Esse é... o veneno?!",
  ui_story_5068_50681001_37_dialog_content = "Mas... por que há veneno saindo da sua pele? Está... Está começando a ficar vermelho brilhante! Precisamos limpar isso da sua pele imediatamente!",
  ui_story_5068_50681001_38_dialog_content = "Não toque nela!",
  ui_story_5068_50681001_39_dialog_content = "Não toque nela?! Minha irmã está sofrendo, agora me solte! Como você pode ficar aí parado e assistir?!",
  ui_story_5068_50681001_40_dialog_content = "Eu também não quero ver o Rebecca sofrendo! Mas agora...",
  ui_story_5068_50681001_41_dialog_content = "Não há nada que possamos fazer para ajudá-la.",
  ui_story_5068_50681001_42_dialog_content = "Rebecca produziu muito soro mais cedo. A única maneira de ela se estabilizar é expelindo essa quantidade de veneno.",
  ui_story_5068_50681001_43_dialog_content = "Se o equilíbrio entre os dois for quebrado... É provável que ela perca a sanidade.",
  ui_story_5068_50681001_44_dialog_content = "Além disso, esse veneno é extremamente perigoso para a maioria das pessoas. Tenho certeza de que ela não quer que ninguém entre em contato com ele!",
  ui_story_5068_50681001_45_dialog_content = "Hum...",
  ui_story_5068_50681001_46_dialog_content = "Rebecca...",
  ui_story_5068_50681001_47_dialog_content = "Mas ela nunca teve que fazer isso antes! Eu sou a irmã mais velha dela, então como eu nunca soube disso?!",
  ui_story_5068_50681001_48_dialog_content = "É algo que ela decidiu assumir sozinha. Ela também tem seus motivos para fazer isso.",
  ui_story_5068_50681001_49_dialog_content = "Eu não me importo com os motivos dela! Você não pode simplesmente deixar Rebecca se machucar assim!",
  ui_story_5068_50681001_50_dialog_content = "V-Veronica...",
  ui_story_5068_50681001_51_dialog_content = "Eu... Eu escolhi isso para mim, Isa. É meu fardo para carregar... Então não culpe mais ninguém.",
  ui_story_5068_50681001_52_dialog_content = "Eu não queria... que você se preocupasse demais. Mas você ainda... descobriu.",
  ui_story_5068_50681001_53_dialog_content = "Rebecca! Você... Você está se sentindo melhor?",
  ui_story_5068_50681001_54_dialog_content = "Sim... Depois de tirar tudo isso do meu sistema... Eu me sinto bem melhor.",
  ui_story_5068_50681001_55_dialog_content = "Isso é o que você guardou em todos aqueles potes na sua sala escondida? Se sim, isso significa que você já passou por isso várias vezes...",
  ui_story_5068_50681001_56_dialog_content = "Que potes? E sala escondida?! Se você não quer que eu me preocupe, então me conte tudo!",
  ui_story_5068_50681001_57_dialog_content = "Não é... realmente um problema tão grande. É só que... Desde <color=#FFB400>aquele dia</color>, decidi conduzir pesquisas sobre o meu veneno.",
  ui_story_5068_50681001_58_dialog_content = "Talvez seja porque comecei tarde demais ou porque estava com muita pressa, mas... Minha pesquisa resultou nesses efeitos colaterais.",
  ui_story_5068_50681001_59_dialog_content = "Mas não vou parar.",
  ui_story_5068_50681001_60_dialog_content = "Naquela época... eu não conseguia usar meu \"dom\" para ajudar ninguém. Tudo o que eu podia fazer era correr e me esconder como um covarde...",
  ui_story_5068_50681001_61_dialog_content = "Isso não foi sua culpa, Rebecca! Os Lobos Negros são os culpados, não você!",
  ui_story_5068_50681001_62_dialog_content = "Mas... Mas se eu tivesse aprendido a controlar meu veneno antes, talvez pudesse ter impedido que eles invadissem nossa casa...",
  ui_story_5068_50681001_63_dialog_content = "Mesmo agora, ainda tenho pessoas que quero proteger.",
  ui_story_5068_50681001_64_dialog_content = "E se protegê-los significa suportar um pouco mais de dor... Então é um preço que estou disposto a pagar.",
  ui_story_5068_50681001_65_dialog_content = "Isso não pareceu uma dorzinha agora há pouco. Você estava claramente sofrendo... Argh, que tipo de irmã inútil eu sou?!",
  ui_story_5068_50681001_66_dialog_content = "Você não deveria ter que fazer isso... Isso mesmo! Você não precisará mais fazer isso!",
  ui_story_5068_50681001_67_dialog_content = "Vou pedir à Senhora Sheol para oferecer a você um trabalho na guilda. Assim que ela retornar da reunião de negócios, falarei bem de você!",
  ui_story_5068_50681001_68_dialog_content = "Dessa forma, você pode viver e trabalhar com total segurança! Você nunca mais terá que temer pela sua vida ou se machucar com suas pesquisas!",
  ui_story_5068_50681001_69_dialog_content = "Quanto aos detalhes, deixe o resto comigo!",
  ui_story_5068_50681001_70_dialog_content = "Isa... Mesmo depois de todo esse tempo, você ainda me vê como uma criança.",
  ui_story_5068_50681001_71_dialog_content = "É isso que irmãs mais velhas fazem! Não se preocupe, sei exatamente o que fazer!",
  ui_story_5068_50681001_72_dialog_content = "Vou comprar um belo par de pijamas para você enquanto descansa bastante. Te vejo daqui a pouco!",
  ui_story_5068_50681001_73_dialog_content = "...",
  ui_story_5068_50681001_74_dialog_content = "Ainda tem algo te incomodando, Senhorita Rebecca?",
  ui_story_5068_50681001_75_dialog_content = "Não consigo parar de me preocupar com aqueles pacientes de antes. Saímos com tanta pressa que não consegui avaliar nenhum deles mais de perto.",
  ui_story_5068_50681001_76_dialog_content = "Não estamos mais na clínica, então se algo acontecer com eles...",
  ui_story_5068_50681001_77_dialog_content = "Não se preocupe, vou voltar e verificar como eles estão. Deixamos alguns suprimentos médicos para trás, então posso distribuí-los também.",
  ui_story_5068_50681001_78_dialog_content = "Você tá indo embora agora? Mas e se os Lobos Negros ainda estiverem rondando a clínica?",
  ui_story_5068_50681001_79_dialog_content = "Você não está me subestimando, né, PlayerName?",
  ui_story_5068_50681001_80_dialog_content = "De qualquer forma, ainda não me sinto confortável em deixá-la sozinha na Guilda Cloudrover, Srta. Rebecca.",
  ui_story_5068_50681001_81_dialog_content = "Este lugar parece seguro o suficiente. Além disso, PlayerName ainda está aqui e minha irmã deve voltar em breve.",
  ui_story_5068_50681001_82_dialog_content = "Sinto-me muito melhor agora, mas o mesmo não se pode dizer dos nossos pacientes. Eles precisam de nós neste momento.",
  ui_story_5068_50681001_83_dialog_content = "Entendido. Não vou demorar, mas por favor, cuide-se bem enquanto estou fora.",
  ui_story_5068_50681001_84_dialog_content = "Rebecca parece confiar em você, PlayerName, então farei o mesmo.",
  ui_story_5068_50681001_85_dialog_content = "Tá bom.",
  ui_story_5068_50681001_86_dialog_content = "Desculpe, PlayerName... Eu não te assustei agora, não é?",
  ui_story_5068_50681001_87_dialog_content = "De jeito nenhum. Por favor, não se sinta assim.",
  ui_story_5068_50681001_88_dialog_content = "É só que... você poderia me prometer algo?",
  ui_story_5068_50681001_89_dialog_content = "O que foi?",
  ui_story_5068_50681001_90_dialog_content = "Não importa o que aconteça, por favor, não se machuque nunca mais.",
  ui_story_5068_50681001_91_dialog_content = "PlayerName...",
  ui_story_5068_50681001_92_dialog_content = "Vamos ver... Ela definitivamente precisa de coisas para tomar banho, além de uma toalha... Ah, vou comprar um monte de toalhas para ela!",
  ui_story_5068_50681001_93_dialog_content = "Nossa, aposto que Rebecca ficaria super fofo com isso! Agora só preciso...",
  ui_story_5068_50681001_94_dialog_content = "?!",
  ui_story_5068_50681001_95_dialog_content = "*tosse, tosse* Quem está aí? E como você ousa causar problemas... no território da Guilda Cloudrover?!",
  ui_story_5068_50681001_96_dialog_content = "<color=#e8d9bb>Puf—</color>",
  ui_story_5068_50681001_97_dialog_content = "Huh...?!",
  ui_story_5068_50681001_98_dialog_content = "Os Lobos Negros...",
  ui_story_5068_50681101_1_dialog_content = "Espere... Onde estou?",
  ui_story_5068_50681101_2_dialog_content = "E eu estou todo amarrado?! Tsc, esses Lobos Negros sempre recorrem a truques tão baixos.",
  ui_story_5068_50681101_3_dialog_content = "Ainda assim, a maneira como eles me amarraram... Heh, seus ancestrais devem estar tão envergonhados.",
  ui_story_5068_50681101_4_dialog_content = "...",
  ui_story_5068_50681101_5_dialog_content = "Qual é o problema agora? Não consegue falar com uma garota mesmo depois de sequestrá-la?!",
  ui_story_5068_50681101_6_dialog_content = "Diga a quem estiver no comando para sair daqui! Tenho contas a acertar com eles!",
  ui_story_5068_50681101_7_dialog_content = "Isa Svanedona, a filha mais velha da Família Svanedona que, por acaso, estava estudando no exterior na época.",
  ui_story_5068_50681101_8_dialog_content = "Eu me pergunto que tipo de névoa negra seu corpo produzirá quando queimar... Será que causará uma dor insuportável nas pessoas? Ou talvez provoque convulsões incontroláveis?",
  ui_story_5068_50681101_9_dialog_content = "Heheheh. Que pena que você não herdou os dons da sua família.",
  ui_story_5068_50681101_10_dialog_content = "Cale a boca! Minha família pode ter ido embora, mas eu ainda estou aqui e vou me vingar mais cedo ou mais tarde!",
  ui_story_5068_50681101_11_dialog_content = "Sério? Porque você não parece ser bom em nada além de falar alto. Sua irmã, por outro lado...",
  ui_story_5068_50681101_12_dialog_content = "O que você quer com ela?! Eu não vou deixar os Lobos Negros machucarem mais ninguém da minha família!",
  ui_story_5068_50681101_13_dialog_content = "O que eu quero? Heh... Tudo o que quero é terminar o que comecei.",
  ui_story_5068_50681101_14_dialog_content = "Estou te avisando, fique longe da minha irmã... Ou então...",
  ui_story_5068_50681101_15_dialog_content = "Ou então o quê? Espere, deixa eu adivinhar... Você vai se libertar das amarras e me matar onde eu estou?",
  ui_story_5068_50681101_16_dialog_content = "Urgh...! Cale a boca!",
  ui_story_5068_50681102_1_dialog_content = "S-Se você quer chegar até minha irmã... Você vai ter que me matar primeiro...",
  ui_story_5068_50681102_2_dialog_content = "Matar você? Por favor, eu não sou tão estúpido a ponto de enfrentar a Guilda Cloudrover diretamente.",
  ui_story_5068_50681102_3_dialog_content = "Talvez você não seja estúpido o suficiente... Mas ainda é bem estúpido... Hahaha...",
  ui_story_5068_50681102_4_dialog_content = "Já chega de você!",
  ui_story_5068_50681102_5_dialog_content = "Quando você enfrenta um poder avassalador, tudo o que pode fazer é se render e morrer... Depois de todos os meus anos de luta, essa é a única verdade que aprendi.",
  ui_story_5068_50681102_6_dialog_content = "E agora, estou prestes a ensinar a mesma lição a você... Você deveria se sentir grato.",
  ui_story_5068_50681102_7_dialog_content = "<color=#e8d9bb>Baque-</color>",
  ui_story_5068_50681102_8_dialog_content = "É você, Isa?",
  ui_story_5068_50681102_9_dialog_content = "Não... Que estranho, não há ninguém na porta.",
  ui_story_5068_50681102_10_dialog_content = "Huh? Tem uma carta no chão... E está escrito \"Para Rebecca\"!",
  ui_story_5068_50681102_11_dialog_content = "Para mim? Deixe-me ver...",
  ui_story_5068_50681102_12_dialog_content = "Não... Isso não pode ser!",
  ui_story_5068_50681102_13_dialog_content = "É Isa... Ela foi capturada pelos Lobos Negros! Mas ela disse que eles não fariam nada com ela no território da Guilda Cloudrover!",
  ui_story_5068_50681102_14_dialog_content = "Se os Lobos Negros estão dispostos a ignorar as regras de Umbraton... Isso significa que eles estão prontos para lutar abertamente agora.",
  ui_story_5068_50681102_15_dialog_content = "Eleanor ainda não voltou... será que algo aconteceu com ela também?",
  ui_story_5068_50681102_16_dialog_content = "Vamos nos preocupar com isso mais tarde. O que mais a carta diz?",
  ui_story_5068_50681102_17_dialog_content = "Diz que, se quisermos que ela permaneça ilesa, preciso aparecer no esconderijo deles na próxima hora... Há também um endereço escrito aqui.",
  ui_story_5068_50681102_18_dialog_content = "Então eles estavam atrás de você o tempo todo. Você estaria caindo direitinho nas mãos deles se fosse até lá agora!",
  ui_story_5068_50681102_19_dialog_content = "Mas eles sequestraram Isa... Eu não tenho escolha!",
  ui_story_5068_50681102_20_dialog_content = "Como eu poderia abandoná-la quando acabamos de nos encontrar depois de tanto tempo? Além disso, pode haver mais membros da minha família lá...",
  ui_story_5068_50681102_21_dialog_content = "Mas eu prometi encontrar uma maneira de te ajudar...",
  ui_story_5068_50681102_22_dialog_content = "Não há mais tempo... No último ano, eu não fiz nada além de correr e me esconder na minha clínica subterrânea.",
  ui_story_5068_50681102_23_dialog_content = "Eu não tinha como saber se alguém da minha família sobreviveu, ou se eles foram capturados e torturados... Minha covardia é o que causou tudo isso.",
  ui_story_5068_50681102_24_dialog_content = "Apesar disso, eu ainda estou apenas fugindo. Eu... Eu até pedi para você pensar em uma resposta para mim.",
  ui_story_5068_50681102_25_dialog_content = "O objetivo principal de pesquisar meu veneno era encontrar uma maneira de proteger aqueles que me importo, mas não só eu falhei, como também coloquei a vida da minha irmã em risco...",
  ui_story_5068_50681102_26_dialog_content = "Eu não posso continuar fugindo. Não mais.",
  ui_story_5068_50681102_27_dialog_content = "Se seus entes queridos fossem sequestrados, você não mediria esforços para resgatá-los, certo?",
  ui_story_5068_50681102_28_dialog_content = "... Eu sabia que não conseguiria te convencer a desistir, mas isso é muito perigoso para apenas nós dois.",
  ui_story_5068_50681102_29_dialog_content = "A Guilda Cloudrover... Umbraton... Até mesmo gangues...",
  ui_story_5068_50681102_30_dialog_content = "Espere—eu conheço um grupo de mercenários aqui na cidade! Talvez eles possam nos ajudar!",
  ui_story_5068_50681201_1_dialog_content = "Eu nunca imaginei que você aceitaria um trabalho que envolvesse resgatar um refém, PlayerName.",
  ui_story_5068_50681201_2_dialog_content = "É uma longa história... Mas temos que tirar Isa de lá em segurança.",
  ui_story_5068_50681201_3_dialog_content = "Obrigado por aparecer em tão pouco tempo, aliás. Isso deve nos ajudar muito!",
  ui_story_5068_50681201_4_dialog_content = "Não se preocupe! O Capitão Luke não pôde vir pessoalmente, mas daremos tudo de nós!",
  ui_story_5068_50681201_5_dialog_content = "Estamos no esconderijo dos Lobos Negros, então fique atento! A névoa negra é especialmente densa aqui, o que significa que provavelmente estão produzindo-a em algum lugar neste lugar!",
  ui_story_5068_50681201_6_dialog_content = "...",
  ui_story_5068_50681201_7_dialog_content = "<color=#e8d9bb>Creee...</color>",
  ui_story_5068_50681201_8_dialog_content = "Você realmente acha que Isa está aqui? Tudo o que vejo são potes e recipientes.",
  ui_story_5068_50681201_9_dialog_content = "Consigo sentir a presença de Isa por perto, mas esses potes...",
  ui_story_5068_50681201_10_dialog_content = "Há nomes escritos neles...",
  ui_story_5068_50681201_11_dialog_content = "Tio Albert, Jessica... Mãe e Pai... Aaron...",
  ui_story_5068_50681201_12_dialog_content = "Os nomes deles estão nestes potes de veneno, o que significa que todos eles são...",
  ui_story_5068_50681201_13_dialog_content = "Rebecca...",
  ui_story_5068_50681201_14_dialog_content = "Todos esses nomes...",
  ui_story_5068_50681201_15_dialog_content = "Até tem... Até tem um pote grande e vazio com meu nome nele.",
  ui_story_5068_50681201_16_dialog_content = "... M-Mas eu não vejo um com o nome de Isa! Isso significa que não estamos atrasados!",
  ui_story_5068_50681201_17_dialog_content = "Não, PlayerName. Você vê... Isa nunca herdou a habilidade da nossa família.",
  ui_story_5068_50681201_18_dialog_content = "O que significa que ela já pode estar...",
  ui_story_5068_50681201_19_dialog_content = "Não tire conclusões precipitadas ainda. Primeiro, precisamos encontrá-la!",
  ui_story_5068_50681201_20_dialog_content = "Cuidado! O inimigo está se aproximando!",
  ui_story_5068_50681201_21_dialog_content = "<color=#e8d9bb>Toc, toc, toc..</color>",
  ui_story_5068_50681201_22_dialog_content = "Em nome dos Lobos Negros, seja bem-vindo à nossa base de operações.",
  ui_story_5068_50681201_23_dialog_content = "... É Arte, o Diretor dos Lobos Negros!",
  ui_story_5068_50681201_24_dialog_content = "Heheh... Faz algum tempo que este lugar não vê agitação.",
  ui_story_5068_50681201_25_dialog_content = "É rude trazer uma multidão para a festa quando eu só convidei você... Rebecca Svanedona.",
  ui_story_5068_50681201_26_dialog_content = "Que pena. Se você tivesse chegado aqui um pouco mais cedo, talvez tivesse tido a chance de vê-lo pela última vez... Seu pai, acredito eu? O homem tinha uma determinação incrível; de todos os meus cobaias, ele resistiu por mais tempo.",
  ui_story_5068_50681201_27_dialog_content = "Você...!",
  ui_story_5068_50681201_28_dialog_content = "No começo, eu só queria descontar meu ódio na Família Svanedona, mas quando descobri seu segredo... soube que fui escolhido para algo maior.",
  ui_story_5068_50681201_29_dialog_content = "Você também não deveria ficar tão chateado comigo. Afinal, se eu não os tivesse aprisionado, eles não teriam vivido para ver outro ano. Você não concorda?",
  ui_story_5068_50681201_30_dialog_content = "Além disso, se alguém é culpado... São eles por não produzirem seu veneno até depois de morrerem. Eu não consigo fazer minha névoa negra sem ele.",
  ui_story_5068_50681201_31_dialog_content = "Mas você é diferente, Rebecca. Vou ter certeza de valorizar você pelo maior tempo possível—",
  ui_story_5068_50681201_32_dialog_content = "Eu não vou deixar você fazer nada com ela nunca mais!",
  ui_story_5068_50681201_33_dialog_content = "Oh? Acho que te reconheço. Você é... o Celestita, não é?",
  ui_story_5068_50681201_34_dialog_content = "Tch... Se ao menos pudéssemos ter nos conhecido em outras circunstâncias.",
  ui_story_5068_50681201_35_dialog_content = "Já ouvi falar dos seus poderes antes... Talvez tenhamos a chance de trabalhar juntos no futuro?",
  ui_story_5068_50681201_36_dialog_content = "Eu nunca trabalharia com um idiota desumano como você! Agora, onde está Isa?!",
  ui_story_5068_50681201_37_dialog_content = "A rixa entre os Lobos Negros e a Família Svanedona não deveria preocupar um Celestita, então, por favor, você poderia se afastar por enquanto?",
  ui_story_5068_50681201_38_dialog_content = "Nos seus sonhos! Estou aqui para ajudar minha amiga a resgatar a família dela!",
  ui_story_5068_50681201_39_dialog_content = "E aqui estava eu tentando ser um bom anfitrião. Que ridículo.",
  ui_story_5068_50681201_40_dialog_content = "Traga-a para fora!",
  ui_story_5068_50681201_41_dialog_content = "...",
  ui_story_5068_50681201_42_dialog_content = "Isa!!",
  ui_story_5068_50681201_43_dialog_content = "Urgh... Rebecca? O que você está fazendo aqui?!",
  ui_story_5068_50681201_44_dialog_content = "Você não deveria ter vindo aqui! Como pôde cair em uma armadilha tão óbvia?! Não se preocupe comigo, apenas corra antes que seja tarde demais!",
  ui_story_5068_50681201_45_dialog_content = "Solte minha irmã!",
  ui_story_5068_50681201_46_dialog_content = "Claro, eu ficaria mais do que feliz em deixá-la ir. Mas—",
  ui_story_5068_50681201_47_dialog_content = "Você precisa ficar no lugar dela.",
  ui_story_5068_50681201_48_dialog_content = "O que você quer?",
  ui_story_5068_50681201_49_dialog_content = "Não fui claro o suficiente? Rebecca precisa ficar com os Lobos Negros.",
  ui_story_5068_50681201_50_dialog_content = "Não vou machucar um único fio de cabelo dela; afinal, ela é a única que pode me ajudar a aprofundar minha pesquisa sobre a névoa negra. Estou até disposto a deixar o passado para trás.",
  ui_story_5068_50681201_51_dialog_content = "Também posso apresentar a <color=#FFB400>mulher</color> que a recomendou para mim em primeiro lugar.",
  ui_story_5068_50681201_52_dialog_content = "Mas se ela sair da linha uma única vez... Heheheh, fique à vontade para tentar, Rebecca.",
  ui_story_5068_50681201_53_dialog_content = "Saiba que a cooperação não é apenas do seu interesse. É também a única escolha que lhe resta.",
  ui_story_5068_50681201_54_dialog_content = "Você está brincando comigo? Falando sobre coisas passadas e alguma mulher... Rebecca é claramente a vítima aqui!",
  ui_story_5068_50681201_55_dialog_content = "Oh? Tudo bem se o Caelestite não souber de nada, mas você Rebecca? Não me diga que você tem escondido os segredos da sua família apenas para tirar proveito da confiança dele?",
  ui_story_5068_50681201_56_dialog_content = "Eu não tenho ideia do que está falando.",
  ui_story_5068_50681201_57_dialog_content = "Se for esse o caso, então sua irmã não te contou o que aconteceu entre os Lobos Negros e a Família Svanedona.",
  ui_story_5068_50681201_58_dialog_content = "Naquela época, tudo o que eu queria era convidar você para trabalhar comigo, mas a Família Svanedona desprezava nós, Lobos Negros. Eles não apenas nos rejeitaram, como também feriram muitos de nossos membros.",
  ui_story_5068_50681201_59_dialog_content = "Mentiroso! Os Lobos Negros foram os primeiros a sair da linha! A luta só começou porque vocês bandidos deram o primeiro passo!",
  ui_story_5068_50681201_60_dialog_content = "Cale a boca dela.",
  ui_story_5068_50681201_61_dialog_content = "Sim!",
  ui_story_5068_50681201_62_dialog_content = "Hum, hum, hum—",
  ui_story_5068_50681201_63_dialog_content = "Me convide para trabalhar com você?",
  ui_story_5068_50681201_64_dialog_content = "Ah? Eu estava certo, parece que você não faz ideia do que realmente aconteceu.",
  ui_story_5068_50681201_65_dialog_content = "Depois de todo esse tempo, nem mesmo seu amigo mais próximo teve coragem de te contar?",
  ui_story_5068_50681201_66_dialog_content = "Ela sabe muito bem o que aconteceu naquela época. Afinal, ela mesma costumava ser uma Loba Negra.",
  ui_story_5068_50681201_67_dialog_content = "...!!",
  ui_story_5068_50681201_68_dialog_content = "Você não quer dizer... Eleanor?",
  ui_story_5068_50681301_1_dialog_content = "Você não quer dizer... Eleanor?",
  ui_story_5068_50681301_2_dialog_content = "Heheheh. Surpreso?",
  ui_story_5068_50681301_3_dialog_content = "Eleanor acontece de ser um dos membros mais antigos da história dos Lobos Negros.",
  ui_story_5068_50681301_4_dialog_content = "Eu a enviei para se infiltrar na família Svanedona há muito tempo... para coletar todas as informações possíveis sobre eles.",
  ui_story_5068_50681301_5_dialog_content = "Você poderia até dizer que a queda de toda a família foi graças a ela.",
  ui_story_5068_50681301_6_dialog_content = "Eleanor... N-Não... Isso é impossível!",
  ui_story_5068_50681301_7_dialog_content = "No dia em que nossa família foi atacada... Eleanor arriscou sua vida para me salvar!",
  ui_story_5068_50681301_8_dialog_content = "Ela esteve ao meu lado desde então, não importa o que aconteceu conosco!",
  ui_story_5068_50681301_9_dialog_content = "Eleanor não poderia ser um de vocês!",
  ui_story_5068_50681301_10_dialog_content = "Estou apenas expondo os fatos, nada mais. Trair os outros é um hábito difícil de abandonar, Rebecca; seria inteligente lembrar disso.",
  ui_story_5068_50681301_11_dialog_content = "Estou surpreso que o herói dos Lobos Negros não esteja aqui com você hoje. Não que eu realmente me importe, já que você é o único que me interessa, Rebecca Svanedona.",
  ui_story_5068_50681301_12_dialog_content = "...",
  ui_story_5068_50681301_13_dialog_content = "(Se Eleanor não foi capturada, isso significa que ela provavelmente está de volta à clínica agora...)",
  ui_story_5068_50681301_14_dialog_content = "(Aquele olhar nos olhos de Rebecca... O que ela poderia estar pensando?)",
  ui_story_5068_50681301_15_dialog_content = "Mas chega de falar sobre isso. Você já tem uma resposta para mim, Rebecca?",
  ui_story_5068_50681301_16_dialog_content = "Não—!!!",
  ui_story_5068_50681301_17_dialog_content = "Hum, hum, hum...",
  ui_story_5068_50681301_18_dialog_content = "Isa!!!",
  ui_story_5068_50681301_19_dialog_content = "Aquela lâmina pendurada sobre a cabeça dela não é só para enfeite, viu?",
  ui_story_5068_50681301_20_dialog_content = "No final do dia, a única coisa que eu quero é esse seu poder.",
  ui_story_5068_50681301_21_dialog_content = "Se você tivesse se juntado a nós em vez de se esconder como um covarde no último ano, as pessoas naqueles potes não teriam morrido de maneira tão vergonhosa.",
  ui_story_5068_50681301_22_dialog_content = "Mas agora estou te dando uma última chance. Se você não quer que sua irmã acabe como os outros, admita que foi tudo culpa sua! Admita que você é a filha do desastre!",
  ui_story_5068_50681301_23_dialog_content = "A filha do desastre...",
  ui_story_5068_50681301_24_dialog_content = "... Isso é realmente tudo culpa minha? A queda da minha família... O veneno nocivo que nunca para de fluir de mim...",
  ui_story_5068_50681301_25_dialog_content = "Desde que nasci, eu nunca pude tocar coisas boas como uma pessoa normal...",
  ui_story_5068_50681301_26_dialog_content = "Não dê ouvidos a ela, Rebecca! Veja só o que ela fez com toda a sua família! Você não tem motivo para se render a ela!",
  ui_story_5068_50681301_27_dialog_content = "Talvez sim, mas que outra escolha ela tem?",
  ui_story_5068_50681301_28_dialog_content = "O veneno em seu corpo será o fim dela algum dia. Em vez de deixá-lo ser desperdiçado, por que não me deixar fazer algo útil com ele?",
  ui_story_5068_50681301_29_dialog_content = "...",
  ui_story_5068_50681301_30_dialog_content = "(Se isso continuar, Rebecca pode realmente fazer essa escolha...)",
  ui_story_5068_50681301_31_dialog_content = "(Como um celestita, deve haver algo que eu possa fazer!)",
  ui_story_5068_50681301_32_option_content = "Aumento de Força!",
  ui_story_5068_50681301_33_dialog_content = "(Rebecca! Rebecca!)",
  ui_story_5068_50681301_34_dialog_content = "(... PlayerName? Isso é... um dos seus poderes também?)",
  ui_story_5068_50681301_35_dialog_content = "(Por favor, apenas me ouça! Não há tempo para explicar!)",
  ui_story_5068_50681301_36_dialog_content = "(Desculpe mesmo que sua família tenha tido esse fim... Mas confie em mim quando digo que nada disso é culpa sua!)",
  ui_story_5068_50681301_37_dialog_content = "(Como você poderia ser a \"filha do desastre\" quando se machuca tanto apenas para salvar seus pacientes? Se for o caso, você é um anjo da guarda de Umbraton!)",
  ui_story_5068_50681301_38_dialog_content = "(Se você não acredita em mim, tente usar seus poderes para resgatar Isa agora mesmo!)",
  ui_story_5068_50681301_39_dialog_content = "(Meus poderes... Será que posso realmente usá-los para salvá-la?)",
  ui_story_5068_50681301_40_dialog_content = "(Se eu lutar com toda a minha força—)",
  ui_story_5068_50681301_41_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5068_50681301_42_dialog_content = "D... Diretor...",
  ui_story_5068_50681301_43_dialog_content = "Você consegue, Rebecca!",
  ui_story_5068_50681301_44_dialog_content = "Isa!!!",
  ui_story_5068_50681301_45_dialog_content = "Mmm, mmm—!!",
  ui_story_5068_50681301_46_dialog_content = "<color=#e8d9bb>Clic.</color>",
  ui_story_5068_50681301_47_dialog_content = "Pare de resistir. É tão perigoso quanto inútil.",
  ui_story_5068_50681301_48_dialog_content = "Nem mesmo você pode curar um ferimento de bala na cabeça, Rebecca.",
  ui_story_5068_50681301_49_dialog_content = "Mmm, mmm—!!",
  ui_story_5068_50681301_50_dialog_content = "...!!",
  ui_story_5068_50681301_51_dialog_content = "Isa—Não!",
  ui_story_5068_50681301_52_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5068_50681301_53_dialog_content = "<color=#e8d9bb>Bang! Bang! Bang!</color>",
  ui_story_5068_50681301_54_dialog_content = "Urgh—! Quem fez isso?!",
  ui_story_5068_50681301_55_dialog_content = "Agora é a hora, irmãos!",
  ui_story_5068_50681301_56_dialog_content = "Sim!",
  ui_story_5068_50681301_57_dialog_content = "...",
  ui_story_5068_50681301_58_dialog_content = "?!",
  ui_story_5068_50681301_59_dialog_content = "<color=#e8d9bb>Toc toc toc..</color>",
  ui_story_5068_50681301_60_dialog_content = "É você! Como ousa atirar em mim, Eleanor—!!!",
  ui_story_5068_50681301_61_dialog_content = "O que? Você ouviu tudo? Ou será que eu contei a história errada?",
  ui_story_5068_50681301_62_dialog_content = "Já chega!!",
  ui_story_5068_50681301_63_dialog_content = "Desculpe por aparecer tão tarde, Senhorita Rebecca. Você está bem?",
  ui_story_5068_50681301_64_dialog_content = "Quando voltei à Guilda Cloudrover, tudo que encontrei foi uma sala vazia e um bilhete de resgate... Então vim para cá o mais rápido que pude.",
  ui_story_5068_50681301_65_dialog_content = "Estou bem, Eleanor, mas por favor vá verificar Isa.",
  ui_story_5068_50681301_66_dialog_content = "Isa! Você está bem?!",
  ui_story_5068_50681301_67_dialog_content = "Estávamos procurando por você quando Eleanor nos disse que você foi sequestrado, então corremos para cá com ela!",
  ui_story_5068_50681301_68_dialog_content = "... Eu estou bem! Na verdade... Estou melhor que bem! É hora de retribuir a hospitalidade dos Lobos Negros, então preparem-se para uma luta!",
  ui_story_5068_50681301_69_dialog_content = "Mas você parece realmente machucado, Isa! Devemos sair daqui enquanto temos a chance!",
  ui_story_5068_50681301_70_dialog_content = "PlayerName está certo... Vou abrir um caminho para sair daqui!",
  ui_story_5068_50681301_71_dialog_content = "Estou com você, Srta. Rebecca!",
  ui_story_5068_50681301_72_dialog_content = "Tudo bem, vou apoiar todos em batalha também!",
  ui_story_5068_50681302_1_dialog_content = "Perdoe-nos, Diretor... Deixamos eles escaparem.",
  ui_story_5068_50681302_2_dialog_content = "...",
  ui_story_5068_50681302_3_dialog_content = "Diretor?",
  ui_story_5068_50681302_4_dialog_content = "Tudo bem. Não me importo de brincar com eles um pouco mais, já que gostam tanto de se esforçar.",
  ui_story_5068_50681302_X4_dialog_content = "Posso contar nos dedos de uma mão o número de lugares que eles podem ir. Vamos preparar um belo presente de boas-vindas para eles antes de irmos até lá...",
  ui_story_5068_50681302_X5_dialog_content = "Já está na hora de usarmos nosso trunfo, agora vá prepará-lo!",
  ui_story_5068_50681302_5_dialog_content = "Hoje não será diferente do dia em que a Família Svanedona morreu... Tudo isso porque vocês, tolos, me forçaram a agir!",
  ui_story_5068_50681302_6_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat, pit-pat...</color>",
  ui_story_5068_50681302_7_dialog_content = "Ufa—eu... eu acho que eles não estão mais nos perseguindo...",
  ui_story_5068_50681302_X7_dialog_content = "Devo dizer, vocês mercenários realmente sabem se virar! Mas não deveríamos nos preocupar com os caras que cobriram nossa fuga...?",
  ui_story_5068_50681302_X8_dialog_content = "Somos todos profissionais, não há necessidade de se preocupar com eles. Eles se reunirão conosco em breve.",
  ui_story_5068_50681302_8_dialog_content = "Estamos correndo há tanto tempo... Estão todos bem?",
  ui_story_5068_50681302_9_dialog_content = "... Não pare ainda! Este lugar não é seguro e Arte não nos deixará ir tão facilmente!",
  ui_story_5068_50681302_10_dialog_content = "...",
  ui_story_5068_50681302_11_dialog_content = "Como você está aguentando, Rebecca? Mesmo com minha ferida, você ainda parece pior do que eu!",
  ui_story_5068_50681302_12_dialog_content = "Eu... eu vou ficar bem. Vamos apenas encontrar um lugar seguro primeiro...",
  ui_story_5068_50681302_13_dialog_content = "Aguente firme, senhorita Rebecca!",
  ui_story_5068_50681302_14_dialog_content = "Há alguns armazéns abandonados mais à frente. Podemos parar e recuperar o fôlego lá!",
  ui_story_5068_50681302_15_dialog_content = "Meus homens e eu ficaremos de olho, então vá em frente e descanse um pouco. Não ficaremos aqui por muito mais tempo.",
  ui_story_5068_50681302_16_dialog_content = "Deixe-me ajudá-la a sentar, Srta. Rebecca...",
  ui_story_5068_50681302_17_dialog_content = "Espere aí! Me responda uma pergunta agora mesmo: quem diabos é você—",
  ui_story_5068_50681302_18_dialog_content = "Isa!",
  ui_story_5068_50681302_19_dialog_content = "...",
  ui_story_5068_50681302_20_dialog_content = "Apenas pare, Isa... Eu não quero saber.",
  ui_story_5068_50681302_21_dialog_content = "Eleanor arriscou sua vida para me salvar dos Lobos Negros duas vezes... Isso é tudo que eu preciso saber... Nada mais.",
  ui_story_5068_50681302_22_dialog_content = "Mas também é culpa dela! Ela é a razão pela qual perdemos nossa família!",
  ui_story_5068_50681302_23_dialog_content = "Isso não é o Eleanor que eu conheço...",
  ui_story_5068_50681302_24_dialog_content = "A Eleanor que eu conheço cuida de mim quando eu perco a consciência... Ela enfaixa as feridas dos nossos pacientes e faz sopa para as crianças na nossa clínica. Ela—",
  ui_story_5068_50681302_25_dialog_content = "Senhorita Rebecca!",
  ui_story_5068_50681302_26_dialog_content = "Estou emocionado que você pense tão gentilmente de mim... Mas quanto mais você menciona essas coisas, mais culpa eu sinto.",
  ui_story_5068_50681302_27_dialog_content = "Eu... Eu tenho uma confissão a fazer—",
  ui_story_5068_50681302_28_dialog_content = "Não... Eleanor, por favor...",
  ui_story_5068_50681302_29_dialog_content = "É tudo verdade... Cada palavra.",
  ui_story_5068_50681302_30_dialog_content = "Você...?!",
  ui_story_5068_50681302_31_dialog_content = "É verdade que eu costumava ser membro dos Lobos Negros e que fui enviado para infiltrar a Família Svanedona.",
  ui_story_5068_50681302_32_dialog_content = "A razão pela qual me aproximei tanto de você foi para extrair informações dela.",
  ui_story_5068_50681302_33_dialog_content = "Sinto muito, senhorita Rebecca.",
  ui_story_5068_50681401_1_dialog_content = "Não consigo me lembrar do rosto de nenhum dos meus pais. Desde que me lembro, vivia dia após dia, roubando o que podia para me manter alimentado. Até mesmo as outras pessoas nas favelas não suportavam a minha presença.",
  ui_story_5068_50681401_2_dialog_content = "Eu estava deitado em uma pilha de lixo um dia, morrendo de fome... Foi quando os Lobos Negros me acolheram.",
  ui_story_5068_50681401_3_dialog_content = "Naquela época, os Lobos Negros eram completamente diferentes do que são hoje. Eles eram como uma grande família, e eu estava longe de ser o único jovem indefeso entre eles.",
  ui_story_5068_50681401_4_dialog_content = "Arte foi quem liderou nossa luta pela sobrevivência e nos disse para sempre cuidarmos um do outro.",
  ui_story_5068_50681401_5_dialog_content = "Lentamente, mas com certeza, cada vez mais pessoas se juntaram aos Lobos Negros. Os objetivos de Arte também se tornaram mais ambiciosos, e foi por isso que começamos a lutar contra outras gangues.",
  ui_story_5068_50681401_6_dialog_content = "Fiquei furioso quando soube que a Família Svanedona havia machucado meus irmãos e irmãs nos Lobos Negros. Eu achava que os Svanedonas não passavam de bandidos que intimidavam os fracos... Afinal, quem poderia perdoar pessoas por machucar minha própria família?",
  ui_story_5068_50681401_7_dialog_content = "Logo depois, Arte me deu a ordem para me infiltrar na Família Svanedona e me aproximar da Srta. Rebecca. Eu deveria esperar o momento perfeito para sequestrá-la...",
  ui_story_5068_50681401_8_dialog_content = "Mas depois de passar dia após dia feliz com você, algo estranho começou a acontecer comigo...",
  ui_story_5068_50681401_9_dialog_content = "Você me tratou como se eu fosse da família. Sua confiança e gentileza também tocaram os corações do resto de sua família.",
  ui_story_5068_50681401_10_dialog_content = "...",
  ui_story_5068_50681401_11_dialog_content = "Para os Lobos Negros, se machucar é vergonhoso, mas com você e sua família foi diferente. Sempre que eu me machucava, você não respondia com zombaria, mas com amor e bondade.",
  ui_story_5068_50681401_12_dialog_content = "Para mim, é isso que realmente significa ser uma família.",
  ui_story_5068_50681401_13_dialog_content = "Antes de saber qual era o verdadeiro objetivo de Arte, tentei convencer Arte a se aproximar de você de uma maneira mais pacífica. Infelizmente, todos nós sabemos como isso terminou.",
  ui_story_5068_50681401_14_dialog_content = "Eu estava em conflito e não sabia o que fazer — eu não podia trair os Lobos Negros, mas também não conseguia me obrigar a machucar a Srta. Rebecca de forma alguma.",
  ui_story_5068_50681401_15_dialog_content = "No final, tomei uma decisão que vou me arrepender pelo resto da minha vida—",
  ui_story_5068_50681401_16_dialog_content = "Eu fugi.",
  ui_story_5068_50681401_17_dialog_content = "E porque eu fugi, Arte e os Lobos Negros tiveram a chance de atacar a Família Svanedona.",
  ui_story_5068_50681401_18_dialog_content = "Eu tinha esperanças de que a Srta. Rebecca estivesse bem. Quando finalmente voltei, encontrei-a frente a frente com um Arte sanguinário.",
  ui_story_5068_50681401_19_dialog_content = "Ela estava gritando loucamente no topo de seus pulmões, dizendo coisas como: \"Como ousa me desprezar! E o destino dos Lobos Negros!!!\" Ela era uma pessoa completamente diferente da Arte que eu conhecia.",
  ui_story_5068_50681401_20_dialog_content = "Ela sempre foi tão protetora de sua família no passado. Eu não fazia ideia do que aconteceu para fazê-la mudar assim; tudo o que eu sabia era que eu precisava salvar a senhorita Rebecca e tirá-la de lá imediatamente.",
  ui_story_5068_50681401_21_dialog_content = "...",
  ui_story_5068_50681401_22_dialog_content = "Você acha que dizer alguma coisa disso fará com que nós te perdoemos? Rebecca e eu perdemos nossa família inteira, seu assassino!",
  ui_story_5068_50681401_23_dialog_content = "...",
  ui_story_5068_50681401_24_dialog_content = "Rebecca, eu sei que não mereço seu perdão, muito menos toda a confiança e gentileza que você me mostrou no último ano.",
  ui_story_5068_50681401_25_dialog_content = "Uma pessoa como eu não tem o direito de viver...",
  ui_story_5068_50681401_26_dialog_content = "Então, por favor, apenas me mate, Senhorita Rebecca!",
  ui_story_5068_50681401_27_dialog_content = "...",
  ui_story_5068_50681401_28_dialog_content = "Como você ousa! Você sabe que Rebecca nunca faria algo assim! Mesmo agora, você ainda está apenas se aproveitando da bondade dela, seu—",
  ui_story_5068_50681401_29_dialog_content = "Eleanor, você já considerou que tipo de vida Rebecca teria se ela te matasse?",
  ui_story_5068_50681401_30_dialog_content = "Mas eu não mereço nada melhor!",
  ui_story_5068_50681401_31_dialog_content = "Se isso fizesse ela se sentir melhor, mesmo que só um pouquinho...",
  ui_story_5068_50681401_32_dialog_content = "<color=#e8d9bb>Bate, bate!</color>",
  ui_story_5068_50681401_33_dialog_content = "O que está acontecendo lá fora...?",
  ui_story_5068_50681401_34_dialog_content = "Alguém se aproxima! Precisamos sair daqui!",
  ui_story_5068_50681401_35_dialog_content = "Não... Como os Lobos Negros nos alcançaram tão rapidamente?!",
  ui_story_5068_50681401_36_dialog_content = "Vamos, Senhorita Rebecca!",
  ui_story_5068_50681401_37_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_5068_50681401_38_dialog_content = "Aqui!",
  ui_story_5068_50681401_39_dialog_content = "Foi mais fácil do que eu esperava. Parece que nosso joguinho de gato e rato acabou agora.",
  ui_story_5068_50681401_40_dialog_content = "Chega de todo esse esforço inútil. Venha calmamente e talvez eu deixe alguns cadáveres para serem enterrados depois!",
  ui_story_5068_50681401_41_dialog_content = "Ninguém vai acompanhar quieto um lixo como você! Peguem-na, homens!",
  ui_story_5068_50681401_42_dialog_content = "Entendido!",
  ui_story_5068_50681401_43_dialog_content = "Cuidado! Ela está carregando algo perigoso nas mãos!",
  ui_story_5068_50681402_1_dialog_content = "<color=#e8d9bb>Sibilo—</color>",
  ui_story_5068_50681402_2_dialog_content = "*Cof Cof*",
  ui_story_5068_50681402_3_dialog_content = "Esta névoa negra...",
  ui_story_5068_50681402_4_dialog_content = "O que está acontecendo? Eu pensei que Rebecca fosse imune à névoa negra?!",
  ui_story_5068_50681402_5_dialog_content = "Eu realmente sinto pena de você, Rebecca. Nascido em uma família com habilidades inatas tão incríveis... Estou impressionado que nenhum de vocês tenha pensado em pesquisar os segredos por trás de seus poderes.",
  ui_story_5068_50681402_6_dialog_content = "Mas tudo bem. Eu já fiz grande parte disso para você e tenho orgulho de apresentar os frutos da minha pesquisa—",
  ui_story_5068_50681402_7_dialog_content = "Uma névoa negra capaz de neutralizar seu veneno.",
  ui_story_5068_50681402_8_dialog_content = "Mas... como...",
  ui_story_5068_50681402_9_dialog_content = "Heheh, você não acha que tem algo especial nesta névoa? Algo incrivelmente familiar, talvez?",
  ui_story_5068_50681402_10_dialog_content = "O que... O que você está tentando dizer...?",
  ui_story_5068_50681402_11_dialog_content = "Isso não te lembra do abraço quente dos seus pais?",
  ui_story_5068_50681402_12_dialog_content = "Que diabos essa mulher maluca está falando?!",
  ui_story_5068_50681402_13_dialog_content = "Ao contrário dos seus familiares mesquinhos, estou mais do que feliz em compartilhar a fórmula dessa névoa negra com você.",
  ui_story_5068_50681402_14_dialog_content = "Esta névoa... já foi seu precioso pai/mãe.",
  ui_story_5068_50681402_15_dialog_content = "—?!",
  ui_story_5068_50681402_16_dialog_content = "Após um ano inteiro de pesquisa, finalmente descobri o segredo da Família Svanedona: os pais da sua família têm um efeito neutralizador e até corrosivo nas habilidades de seus filhos.",
  ui_story_5068_50681402_17_dialog_content = "É graças a isso, Rebecca, que eu posso manter você tão bem comportado. Eu deveria agradecer ao seu pai/mãe por me poupar tanto esforço.",
  ui_story_5068_50681402_18_dialog_content = "C-Como você pôde fazer algo tão cruel? Usar a família dela contra ela...",
  ui_story_5068_50681402_19_dialog_content = "Arte! Você... Você perdeu a cabeça?! Não se lembra do que sempre nos disse?! \"As piores pessoas do mundo são aquelas que atacam descaradamente os fracos!\"",
  ui_story_5068_50681402_20_dialog_content = "Olhe só para você agora! Até um ano atrás, eu ainda tinha alguma simpatia por você, pois achava que estava apenas em busca de vingança. Mas agora vejo que você é uma pessoa totalmente diferente!",
  ui_story_5068_50681402_21_dialog_content = "O que poderia ter te transformado assim? Foi a emoção do poder e de matar?",
  ui_story_5068_50681402_22_dialog_content = "Ou talvez você sempre tenha sido assim? Você esteve nos usando desde o começo...?",
  ui_story_5068_50681402_23_dialog_content = "Hehe... Hahahaha! O que você saberia?!",
  ui_story_5068_50681402_24_dialog_content = "Eu te encontrei morrendo de fome no lixo, um miserável tão patético que até os cachorros olhavam com desprezo! Onde você estaria agora se não fosse por mim?!",
  ui_story_5068_50681402_25_dialog_content = "Os Lobos Negros nunca teriam sobrevivido tanto tempo se eu não tivesse mentido, trapaceado e roubado a cada passo do caminho!",
  ui_story_5068_50681402_26_dialog_content = "É por isso que você transformou nossos irmãos e irmãs dos Lobos Negros em ferramentas para seu benefício pessoal?!",
  ui_story_5068_50681402_27_dialog_content = "Se for assim, então trair você foi a decisão mais inteligente que já tomei na minha vida.",
  ui_story_5068_50681402_28_dialog_content = "Chega!",
  ui_story_5068_50681402_29_dialog_content = "<color=#e8d9bb>Clic.</color>",
  ui_story_5068_50681402_30_dialog_content = "... Traidores não têm direito de criticar os Lobos Negros.",
  ui_story_5068_50681402_31_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5068_50681402_32_dialog_content = "Heh. Parece que sua habilidade de atirar enferrujou, Diretor.",
  ui_story_5068_50681402_33_dialog_content = "Tsc.",
  ui_story_5068_50681402_34_dialog_content = "<color=#e8d9bb>Bam, bam, bam!</color>",
  ui_story_5068_50681402_35_dialog_content = "Não... Pare com isso... Urgh...",
  ui_story_5068_50681402_36_dialog_content = "Não adianta lutar até o amargo fim, Rebecca.",
  ui_story_5068_50681402_37_dialog_content = "Mortos ou vivos, ainda posso usar vocês para continuar minha pesquisa, então não digam que nunca dei a vocês uma chance de sobreviver! Todos vocês vão morrer aqui!",
  ui_story_5068_50681402_38_dialog_content = "... Cuidado, Senhorita Rebecca!",
  ui_story_5068_50681402_39_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5068_50681402_40_dialog_content = "<color=#e8d9bb>Jato!</color>",
  ui_story_5068_50681402_41_dialog_content = "<size=50>Eleanor?!</size>",
  ui_story_5068_50681402_42_dialog_content = "Não... Por que vocês estão apenas parados?! O inimigo está bem na frente de vocês, então atirem!",
  ui_story_5068_50681402_43_dialog_content = "Fogo!",
  ui_story_5068_50681402_44_dialog_content = "Vamos pegá-los!",
  ui_story_5068_50681402_45_dialog_content = "Sim senhor!!!",
  ui_story_5068_50681402_46_dialog_content = "Eleanor... Consegue me ouvir...?",
  ui_story_5068_50681402_47_dialog_content = "Rebecca... Eu nunca pensei que ouviria você... chamar meu nome novamente... Achei que você me abandonaria.",
  ui_story_5068_50681402_48_dialog_content = "Mas se eu puder morrer... em seus braços... então não terei arrependimentos...",
  ui_story_5068_50681402_49_dialog_content = "D-Não diga coisas assim! Eu posso te curar, só me dê um tempo...",
  ui_story_5068_50681402_50_dialog_content = "Não... É tarde demais para mim... Não se incomode desperdiçando seus poderes... em alguém como eu...",
  ui_story_5068_50681402_51_dialog_content = "Apenas saia daqui... e encontre algum lugar... onde eles nunca te encontrarão...",
  ui_story_5068_50681402_52_dialog_content = "Não esqueça, sou médico... Eu nunca poderia abandonar nenhum dos meus pacientes... especialmente você.",
  ui_story_5068_50681402_53_dialog_content = "Argh! Ainda não consigo usar todo o meu poder... Mas como mais eu deveria me recuperar...?",
  ui_story_5068_50681402_54_dialog_content = "Espere... É isso! Os potes e garrafas na clínica! Eu só preciso voltar e reabastecer meu veneno e soro, e então eu posso—",
  ui_story_5068_50681402_55_dialog_content = "A clínica... não é segura...",
  ui_story_5068_50681402_56_dialog_content = "Não há necessidade... de arriscar sua vida por mim...",
  ui_story_5068_50681402_57_dialog_content = "Apenas... corra...",
  ui_story_5068_50681402_58_dialog_content = "Ela está atrás de você, Rebecca! Vou pedir para minha equipe cobrir Eleanor enquanto você foge!",
  ui_story_5068_50681402_59_dialog_content = "PlayerName, leve Rebecca e encontre uma saída daqui! Estou contando com você!",
  ui_story_5068_50681402_60_dialog_content = "Tudo bem! Vamos lá, Rebecca!",
  ui_story_5068_50681402_61_dialog_content = "Fugindo, não é?",
  ui_story_5068_50681402_62_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5068_50681402_63_dialog_content = "Eu... Eu não vou deixar você atrapalhar o Rebecca! Sua luta... é comigo!",
  ui_story_5068_50681402_64_dialog_content = "Não se bajule.",
  ui_story_5068_50681402_65_dialog_content = "<color=#e8d9bb>Bang, bang!!!</color>",
  ui_story_5068_50681402_66_dialog_content = "Ugh...",
  ui_story_5068_50681402_67_dialog_content = "—!!!",
  ui_story_5068_50681402_68_dialog_content = "C... Correr...",
  ui_story_5068_50681402_69_dialog_content = "Eleanor...",
  ui_story_5068_50681402_70_dialog_content = "... Todos recuem! Saia daqui, Rebecca!",
  ui_story_5068_50681402_71_dialog_content = "Hraaagh—!!",
  ui_story_5068_50681402_72_dialog_content = "Tosse...",
  ui_story_5068_50681402_73_dialog_content = "Como ousa me morder!",
  ui_story_5068_50681402_74_dialog_content = "Fiquem de olho, o resto de vocês! É assim que lidamos com traidores—",
  ui_story_5068_50681402_75_dialog_content = "<color=#e8d9bb>Bang! Bang! Bang! Bang!</color>",
  ui_story_5068_50681402_76_dialog_content = "...",
  ui_story_5068_50681402_77_dialog_content = "<color=#e8d9bb>Bang! Bang! Bang!</color>",
  ui_story_5068_50681402_78_dialog_content = "Ah—! Papai? Papai!!!",
  ui_story_5068_50681402_79_dialog_content = "Correr... Rápido...",
  ui_story_5068_50681402_80_dialog_content = "Rebecca... Corre!",
  ui_story_5068_50681402_81_dialog_content = "<color=#e8d9bb>Pow pow pow pow pow pow!!!</color>",
  ui_story_5068_50681402_82_dialog_content = "Rebecca!",
  ui_story_5068_50681402_83_dialog_content = "Não olhe para trás, Rebecca! Você me ouviu?!",
  ui_story_5068_50681402_84_dialog_content = "... Não deixe o sacrifício de Eleanor ser em vão.",
  ui_story_5068_50681402_85_dialog_content = "Onde está Eleanor, Isa? Você não prometeu salvá-la?",
  ui_story_5068_50681402_86_dialog_content = "Ela está... além de ser salva, Rebecca...",
  ui_story_5068_50681402_87_dialog_content = "Mas como isso pode ser? Eu ainda nem comecei a tratá-la...",
  ui_story_5068_50681402_88_dialog_content = "N-Não... Eu não vou abandonar Eleanor assim...",
  ui_story_5068_50681402_89_dialog_content = "Rebecca... Já é tarde demais agora.",
  ui_story_5068_50681402_90_dialog_content = "PlayerName... Você acha que eu também falhei com ela como médico, não é...?",
  ui_story_5068_50681402_91_dialog_content = "É tudo culpa minha por não conseguir usar meus poderes. Se não fosse por mim, Eleanor ainda estaria...",
  ui_story_5068_50681402_92_dialog_content = "Todo o meu esforço, toda a minha pesquisa, foi tudo para que eu pudesse curar e proteger os outros...",
  ui_story_5068_50681402_93_dialog_content = "Então por que... Por que eu ainda sou tão inútil? Por que tem que ser assim?",
  ui_story_5068_50681402_94_dialog_content = "Espere, é verdade. Ainda tenho todas aquelas garrafas de veneno e soro. Se eu puder usá-los para recuperar meus poderes, posso salvar Eleanor e todos os outros...!",
  ui_story_5068_50681402_95_dialog_content = "Huh? Onde você pensa que está indo, Rebecca?!",
  ui_story_5068_50681501_1_dialog_content = "Espere, Rebecca! Onde você está indo?!",
  ui_story_5068_50681501_2_dialog_content = "Usamos tudo que tínhamos para escapar, e os Lobos Negros podem aparecer a qualquer momento. Precisamos voltar rápido para a Guilda Cloudrover!",
  ui_story_5068_50681501_3_dialog_content = "Eu tenho que... repor meu veneno... e meu soro...",
  ui_story_5068_50681501_4_dialog_content = "... Por favor, não me assuste assim, Rebecca...",
  ui_story_5068_50681501_5_dialog_content = "Eu sei que você está sofrendo muito após perder a Eleanor, mas ela fez o que fez para te salvar! Então, por favor, apenas olhe para mim.",
  ui_story_5068_50681501_6_dialog_content = "Eu tenho que... repor meu veneno...",
  ui_story_5068_50681501_7_dialog_content = "Ela não para de falar sobre repor seu veneno... Acho que ela está tentando voltar para a clínica.",
  ui_story_5068_50681501_8_dialog_content = "Mas será que ela... realmente ficará bem assim?",
  ui_story_5068_50681501_9_dialog_content = "...",
  ui_story_5068_50681501_10_dialog_content = "Rebecca!",
  ui_story_5068_50681501_11_dialog_content = "<color=#e8d9bb>A uma certa distância</color>",
  ui_story_5068_50681501_12_dialog_content = "Diretor... Tem certeza que está bem?",
  ui_story_5068_50681501_13_dialog_content = "Você acha que esses ferimentos podem me parar? Você esqueceu como conseguimos sobreviver todo esse tempo?",
  ui_story_5068_50681501_14_dialog_content = "Me diga, já está pronto?",
  ui_story_5068_50681501_15_dialog_content = "Sim, Diretor.",
  ui_story_5068_50681501_16_dialog_content = "Já chega. Cansei de lidar com toda essa inutilidade. Vou pegar o que quero assim que ela for destruída.",
  ui_story_5068_50681501_17_dialog_content = "Eu me pergunto... Será que meus fogos de artifício deixarão este monte de lixo mais bonito?",
  ui_story_5068_50681501_18_dialog_content = "<color=#e8d9bb>Cabuum!</color>",
  ui_story_5068_50681501_19_dialog_content = "Ahh—",
  ui_story_5068_50681501_20_dialog_content = "Rebecca! Isa!",
  ui_story_5068_50681501_21_dialog_content = "*tossindo* ... Isa?!",
  ui_story_5068_50681501_22_dialog_content = "...",
  ui_story_5068_50681501_23_dialog_content = "Isa! Acorda...!",
  ui_story_5068_50681501_24_dialog_content = "Meu veneno... salvará a todos...",
  ui_story_5068_50681501_25_dialog_content = "Pare, Rebecca! A clínica vai explodir! Não entre lá!!!",
  ui_story_5068_50681501_26_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5068_50681501_27_dialog_content = "Explodiu... Heheh...",
  ui_story_5068_50681501_28_dialog_content = "Eleanor... No final... Eu não consegui nem salvar nossa clínica...",
  ui_story_5068_50681501_29_dialog_content = "...? M-Meus brincos! Onde estão os brincos que o Eleanor me deu?!",
  ui_story_5068_50681501_30_dialog_content = "...",
  ui_story_5068_50681501_31_dialog_content = "Eles se foram... tudo acabou.",
  ui_story_5068_50681501_32_dialog_content = "Rebecca?!",
  ui_story_5068_50681501_33_dialog_content = "Por quê? Por que tem que ser assim...?",
  ui_story_5068_50681501_34_dialog_content = "Minha família se foi, Eleanor se foi, nossa casa se foi e até os brincos que ela fez para mim se foram — não me resta mais nada.",
  ui_story_5068_50681501_35_dialog_content = "Isso não é verdade, Rebecca! E quanto à Isa? Você ainda tem sua irmã!",
  ui_story_5068_50681501_36_dialog_content = "Hum...",
  ui_story_5068_50681501_37_dialog_content = "Re... becca...",
  ui_story_5068_50681501_38_dialog_content = "... Graças a Deus, ela ainda está viva!",
  ui_story_5068_50681501_39_dialog_content = "É muito perigoso lá embaixo, Rebecca! Isa ainda precisa de você, então por favor volte!",
  ui_story_5068_50681501_40_dialog_content = "Isa... precisa de mim...?",
  ui_story_5068_50681501_41_dialog_content = "M-Minha irmã ainda precisa de mim!",
  ui_story_5068_50681501_42_dialog_content = "(Você tem certeza? Afinal, quem poderia precisar de alguém que só traz dor e sofrimento por onde passa?)",
  ui_story_5068_50681501_43_dialog_content = "Fui eu... Eu sou o responsável por tudo isso...",
  ui_story_5068_50681501_44_dialog_content = "(Seu suposto \"dom\" é a causa de todo esse sofrimento. Você realmente acha que merece continuar vivendo?)",
  ui_story_5068_50681501_45_dialog_content = "É verdade... Foi o meu poder que trouxe os Lobos Negros à porta da nossa família. Por minha causa, eles estão todos...",
  ui_story_5068_50681501_46_dialog_content = "Meu poder é o que criou a névoa negra que deixou tantas pessoas doentes nas favelas...",
  ui_story_5068_50681501_47_dialog_content = "(E quanto a Eleanor? Sua morte também está em suas mãos, e não vamos esquecer de sua irmã, que já tem um pé na cova.)",
  ui_story_5068_50681501_48_dialog_content = "(Você não acredita sinceramente que pode derrotar os Lobos Negros com um poder amaldiçoado como o seu, acredita?)",
  ui_story_5068_50681501_49_dialog_content = "(E mesmo que você faça isso, quem pode dizer que outra pessoa não virá em busca do seu poder? Você já perdeu Eleanor; quem vai pagar o preço da próxima vez? As pessoas nas favelas? Isa?)",
  ui_story_5068_50681501_50_dialog_content = "Não! Eu não vou deixar isso acontecer... Mas como... Como posso protegê-los?",
  ui_story_5068_50681501_51_dialog_content = "(Heheh, a resposta é simples. Tudo que você precisa fazer...)",
  ui_story_5068_50681501_52_dialog_content = "(É livrar o mundo da sua existência. Uma vez que você se vá, tudo ficará bem...)",
  ui_story_5068_50681501_53_dialog_content = "*Tosse* Urgh... Isso dói!",
  ui_story_5068_50681501_54_dialog_content = "Você acordou, Isa!",
  ui_story_5068_50681501_55_dialog_content = "Idiota... Pare de se preocupar comigo... Rebecca é quem precisa... Argh—",
  ui_story_5068_50681501_56_dialog_content = "Pare de se mexer! Você só vai perder mais sangue se continuar...",
  ui_story_5068_50681501_57_dialog_content = "Você precisa impedi-la... Ela parece estar prestes a fazer algo imprudente...",
  ui_story_5068_50681501_58_dialog_content = "E-Eu sou irmã dela... Eu sei como ela é, agora vá impedi-la...",
  ui_story_5068_50681501_59_dialog_content = "E-Entendi!",
  ui_story_5068_50681501_60_dialog_content = "Rebecca!",
  ui_story_5068_50681501_61_dialog_content = "Rebecca? O que você está...?",
  ui_story_5068_50681501_62_dialog_content = "... Não chegue mais perto!",
  ui_story_5068_50681501_63_dialog_content = "É perigoso aqui.",
  ui_story_5068_50681501_64_dialog_content = "O que você tá planejando?",
  ui_story_5068_50681501_65_dialog_content = "... A única coisa que posso fazer para parar de machucar as pessoas ao meu redor.",
  ui_story_5068_50681501_66_dialog_content = "V-Você está absorvendo todo esse veneno?!",
  ui_story_5068_50681501_67_dialog_content = "Mas seu corpo... Ele realmente aguenta tudo isso?!",
  ui_story_5068_50681501_68_dialog_content = "Vou ficar bem... Não se preocupe. Não dói nada...",
  ui_story_5068_50681501_69_dialog_content = "Hum...!",
  ui_story_5068_50681501_70_dialog_content = "Pare com isso, Rebecca! Você vai morrer se não parar!",
  ui_story_5068_50681501_71_dialog_content = "Isso mesmo... Estou fazendo isso pelo bem de todos...",
  ui_story_5068_50681501_72_dialog_content = "PlayerName... Eu deveria ter morrido há muito tempo. Não sei o que me fez pensar que eu poderia proteger alguém...",
  ui_story_5068_50681501_73_dialog_content = "Não diga isso! Você me prometeu que não se machucaria mais!",
  ui_story_5068_50681501_74_dialog_content = "Heh, acho que estou voltando atrás na minha palavra... Afinal, isso é Umbraton. Você não pode acreditar em tudo que ouve nesta cidade.",
  ui_story_5068_50681501_75_dialog_content = "Umbraton não tem nada a ver com isso, Rebecca! Você não é esse tipo de pessoa, então pare com isso já! Pense em Isa! Você finalmente tem a chance de estar com sua irmã novamente!",
  ui_story_5068_50681501_76_dialog_content = "Urgh... Tosse, tosse...",
  ui_story_5068_50681501_77_dialog_content = "Isa... Desculpe, mas... Você poderia... ficar de olho nela para mim...?",
  ui_story_5068_50681501_78_dialog_content = "Por favor, diga a ela que eu sinto muito... E que essa é a única maneira de acabar com tudo. Estou fazendo isso por ela também.",
  ui_story_5068_50681501_79_dialog_content = "(Isso mesmo. Se você quer que isso acabe, continue absorvendo esse veneno! Engula tudo!!!)",
  ui_story_5068_50681501_80_dialog_content = "PlayerName... Por favor... Tire minha irmã daqui.",
  ui_story_5068_50681501_81_dialog_content = "Rebecca...",
  ui_story_5068_50681501_82_dialog_content = "Vá... Agora—!!",
  ui_story_5068_50681501_83_dialog_content = "Ahhhh—!!!",
  ui_story_5068_50681501_84_dialog_content = "Isso deve ser suficiente, Rebecca...",
  ui_story_5068_50681501_85_dialog_content = "Deixe o resto comigo.",
  ui_story_5068_50681501_86_dialog_content = "Diretor! Rebecca ainda está viva, e parece que ela absorveu uma grande quantidade de veneno?",
  ui_story_5068_50681501_87_dialog_content = "Mas como?! Onde ela poderia ter encontrado tanto veneno...?",
  ui_story_5068_50681501_88_dialog_content = "É por causa daqueles potes quebrados... O corpo dela está começando a se transformar por absorver tanto disso!",
  ui_story_5068_50681501_89_dialog_content = "... Então, ela está usando o veneno daqueles potes como um \"antídoto\"?",
  ui_story_5068_50681501_90_dialog_content = "Eu não acho que vou conseguir controlá-la depois que ela absorver todo esse veneno... Parece que—",
  ui_story_5068_50681501_91_dialog_content = "\"Parece que minha única escolha é fugir.\" Era isso que você ia dizer?",
  ui_story_5068_50681501_92_dialog_content = "Sheol...",
  ui_story_5068_50681501_93_dialog_content = "Avalie a situação ao redor da clínica e relate-me! Fique seguro lá fora!",
  ui_story_5068_50681501_94_dialog_content = "Sim, Senhora Sheol!",
  ui_story_5068_50681501_95_dialog_content = "Então, você ainda se lembra de mim, afinal, Arte dos Lobos Negros.",
  ui_story_5068_50681501_96_dialog_content = "... Uma clínica decadente como esta não deveria interessar a você ou à Guilda Cloudrover. Por que você trouxe seu pessoal aqui?",
  ui_story_5068_50681501_97_dialog_content = "\"Não deveria nos interessar\", você diz? Nosso pequeno Isa agitado está ferido no chão, e PlayerName parece estar em perigo mortal também.",
  ui_story_5068_50681501_98_dialog_content = "Diga-me, como devo lidar com isso de acordo com nossas regras?",
  ui_story_5068_50681501_99_dialog_content = "De acordo com as regras, a Guilda Cloudrover não tem autoridade nessas favelas.",
  ui_story_5068_50681501_100_dialog_content = "Desculpe decepcioná-lo, mas a partir de hoje, a Guilda Cloudrover está encarregada desta clínica.",
  ui_story_5068_50681501_101_dialog_content = "Agora, como você vai nos retribuir pelo que fez a um dos nossos médicos?",
  ui_story_5068_50681501_102_dialog_content = "...",
  ui_story_5068_50681501_103_dialog_content = "Senhora Sheol! Isa e PlayerName estão seguros por enquanto, mas a situação de Rebecca não parece muito boa! O restante do nosso povo já recuou!",
  ui_story_5068_50681501_104_dialog_content = "Não me diga que...",
  ui_story_5068_50681501_105_dialog_content = "Senhora Sheol! Finalmente você chegou!",
  ui_story_5068_50681501_106_dialog_content = "S-Senhora Sheol! É a Rebecca... Você tem que salvá-la—",
  ui_story_5068_50681501_107_dialog_content = "Morra—!!!",
  ui_story_5068_50681501_108_dialog_content = "... Pobre garota. Veja só o que fizeram com ela.",
  ui_story_5068_50681501_109_dialog_content = "Diretor! Devemos... recuar por enquanto?",
  ui_story_5068_50681501_110_dialog_content = "Não! Use as bombas de névoa negra!",
  ui_story_5068_50681501_111_dialog_content = "<color=#e8d9bb>Sibilo—</color>",
  ui_story_5068_50681501_112_dialog_content = "Não está funcionando?! Mas como—",
  ui_story_5068_50681501_113_dialog_content = "ARTE!!!",
  ui_story_5068_50681501_114_dialog_content = "Tenho um novo trabalho para você, PlayerName! Navegue nossas forças para a batalha!",
  ui_story_5068_50681501_115_dialog_content = "Rebecca precisa da nossa ajuda agora mesmo!",
  ui_story_5068_50681501_116_dialog_content = "... E-Entendi!",
  ui_story_5068_50681502_1_dialog_content = "Jogue mais bombas, seus tolos! Despeje tudo que temos nela!",
  ui_story_5068_50681502_2_dialog_content = "Mas Diretor! Se usarmos tantos de uma vez, nosso equipamento de proteção não nos salvará! Além disso, todos já estão...",
  ui_story_5068_50681502_3_dialog_content = "Não me questione! Não podemos deixar essa mulher insana nos alcançar!",
  ui_story_5068_50681502_4_dialog_content = "*Tossindo* É-É tarde demais, já respiramos isso... Urgh...",
  ui_story_5068_50681502_5_dialog_content = "...",
  ui_story_5068_50681502_6_dialog_content = "Você aí! Leve alguns dos nossos lutadores e não deixe Arte escapar. O resto de vocês ajude a limpar essa bagunça.",
  ui_story_5068_50681502_7_dialog_content = "Entendido!",
  ui_story_5068_50681502_8_dialog_content = "Re... Rebecca...",
  ui_story_5068_50681502_9_dialog_content = "Sou eu... Isa... Por favor, acorde...",
  ui_story_5068_50681502_10_dialog_content = "...",
  ui_story_5068_50681502_11_dialog_content = "Urgh... Onde... estou...?",
  ui_story_5068_50681502_12_dialog_content = "Rebecca! Você finalmente acordou!",
  ui_story_5068_50681502_13_dialog_content = "Graças a Deus—achei que tinha te perdido de novo, Rebecca!",
  ui_story_5068_50681502_14_dialog_content = "—!!",
  ui_story_5068_50681502_15_dialog_content = "Espere, Rebecca! O-Onde você está indo?!",
  ui_story_5068_50681502_16_dialog_content = "D-Não se aproxime de mim!",
  ui_story_5068_50681502_17_dialog_content = "Acho que me transformei em algo diferente agora há pouco... Esta névoa e todas essas pessoas feridas... Fui eu que fiz isso?",
  ui_story_5068_50681502_18_dialog_content = "Tudo o que eu queria era acabar com tudo, mas acabei machucando todos novamente... Eu realmente sou um caso perdido, não sou? Eu não quero causar mais problemas para todos, então apenas me deixem em paz—",
  ui_story_5068_50681502_19_dialog_content = "Não seja estúpido, Rebecca!",
  ui_story_5068_50681502_20_dialog_content = "Isa?!",
  ui_story_5068_50681502_21_dialog_content = "Não! Solte-me! Meu corpo—está coberto de veneno!",
  ui_story_5068_50681502_22_dialog_content = "Não vou soltar! Nem mesmo se eu morrer!",
  ui_story_5068_50681502_23_dialog_content = "Você não quer causar mais problemas para todos? Quando foi que eu me tornei todos?! Eu sou sua irmã! Você pode causar todos os problemas que quiser para mim, e eu ainda não me importaria!",
  ui_story_5068_50681502_24_dialog_content = "Me dizer para te deixar em paz depois de procurar por você por tanto tempo... Isso é uma coisa que eu me recuso a fazer!",
  ui_story_5068_50681502_25_dialog_content = "Sabe de uma coisa? Eu escrevi uma lista de todas as coisas que eu queria fazer com você no dia em que nos encontrássemos de novo! E deixa eu te dizer, é uma lista longa!",
  ui_story_5068_50681502_26_dialog_content = "Quero continuar comprando muitas coisas para você, assim como antes, e vestindo você com roupas bonitas! Eu—",
  ui_story_5068_50681502_27_dialog_content = "Eu não vou te perder nunca mais! Você também não pode me deixar!",
  ui_story_5068_50681502_28_dialog_content = "É uma ordem da sua irmã mais velha, então você tem que ouvir! Está me ouvindo, Rebecca?!",
  ui_story_5068_50681502_29_dialog_content = "Eu... Eu também quero isso, Isa. Eu quero viver o tipo de vida que você acabou de descrever, mas é tarde demais agora. Eu absorvi muito veneno, e logo eu vou estar...",
  ui_story_5068_50681502_30_dialog_content = "Eu só quero encontrar um lugar vazio e tranquilo onde eu possa morrer sozinho.",
  ui_story_5068_50681502_31_dialog_content = "Mesmo assim... Eu vou ficar com você não importa o que aconteça!",
  ui_story_5068_50681502_32_dialog_content = "Você quer um lugar agradável e tranquilo? Então vou te ajudar a encontrar um! Depois disso...",
  ui_story_5068_50681502_33_dialog_content = "Depois disso, vou fazer uma coroa de flores para você, como quando éramos crianças... Vou fazer dezenas, não, centenas delas! Então, por favor, Rebecca—",
  ui_story_5068_50681502_34_dialog_content = "Você precisa soltá-la primeiro, Isa. Caso contrário, você vai...",
  ui_story_5068_50681502_35_dialog_content = "Não! Eu já disse que não vou desistir, mesmo que isso me mate!",
  ui_story_5068_50681502_36_dialog_content = "Espere!",
  ui_story_5068_50681502_37_dialog_content = "... o veneno de Rebecca é suposto corroer a carne. Durante nossa batalha, muitos de nós fomos queimados pelo seu veneno.",
  ui_story_5068_50681502_38_dialog_content = "Então, como você consegue segurá-la com segurança quando ela está completamente coberta de veneno?!",
  ui_story_5068_50681502_39_dialog_content = "... O que você está dizendo?",
  ui_story_5068_50681502_40_dialog_content = "Espere, você está certo! A pele de Rebecca está perfeitamente bem, como sempre!",
  ui_story_5068_50681502_41_dialog_content = "É possível que você realmente tenha herdado uma das habilidades da Família Svanedona, Isa... Uma cura para o veneno de Rebecca, capaz de neutralizar seus efeitos!",
  ui_story_5068_50681502_42_dialog_content = "—!!",
  ui_story_5068_50681502_43_dialog_content = "Não há tempo a perder! Tente fazer algo!",
  ui_story_5068_50681502_44_dialog_content = "Vamos!",
  ui_story_5068_50681502_45_dialog_content = "...",
  ui_story_5068_50681502_46_dialog_content = "Nós iremos?",
  ui_story_5068_50681502_47_dialog_content = "Achei que era só porque Isa estava me segurando... Mas a queimação do meu veneno realmente parece um pouco menos intensa...",
  ui_story_5068_50681502_48_dialog_content = "Isso significa... que funcionou?",
  ui_story_5068_50681502_49_dialog_content = "Sim!",
  ui_story_5068_50681502_50_dialog_content = "Ah, graças a Deus! Eu nunca teria imaginado...",
  ui_story_5068_50681502_51_dialog_content = "Você passou todo esse tempo tratando de todos, mas agora é minha vez de cuidar de você! Não importa quanto tempo leve, não vou parar até que você esteja completamente melhor!",
  ui_story_5068_50681502_52_dialog_content = "Isa...",
  ui_story_5068_50681502_53_dialog_content = "Ah, espera, isso me lembra.",
  ui_story_5068_50681502_54_dialog_content = "Eu encontrei esses antes.",
  ui_story_5068_50681502_55_dialog_content = "Estes são... Os brincos que o Eleanor me deu.",
  ui_story_5068_50681502_56_dialog_content = "... Quer que eu te ajude a colocá-los?",
  ui_story_5068_50681502_57_dialog_content = "... Sim, por favor.",
  ui_story_5068_50681502_58_dialog_content = "Hmm... Agora que penso nisso, esses brincos ficam realmente bonitos em você.",
  ui_story_5068_50681502_59_dialog_content = "...",
  ui_story_5068_50681502_60_dialog_content = "Eleanor... Obrigado por cuidar tão bem da minha irmã. De agora em diante, prometo fazer o mesmo.",
  ui_story_5068_50681601_1_dialog_content = "<color=#e8d9bb>Alguns dias depois</color>",
  ui_story_5068_50681601_2_dialog_content = "Aqui está sua recompensa, conforme prometido. Fique à vontade para verificar se está tudo aí.",
  ui_story_5068_50681601_3_dialog_content = "... Aquele trabalho era muito perigoso, sabe. E por algum motivo, eu não conseguia te alcançar nem mesmo durante os piores momentos...",
  ui_story_5068_50681601_4_dialog_content = "O mundo dos negócios pode ser impiedoso, mas de alguma forma você sempre consegue acertar as coisas, não é?",
  ui_story_5068_50681601_5_dialog_content = "É por isso que, como humilde líder da Guilda Cloudrover, tudo o que posso fazer é pedir a sua paciência e compreensão.",
  ui_story_5068_50681601_6_dialog_content = "Claro, mas... Eu só achei que minha compensação seria um pouco maior depois do que passei.",
  ui_story_5068_50681601_7_dialog_content = "Heheh, você negocia ainda mais duro que Vice quando assume o comando. Vou ter que tomar mais cuidado com você de agora em diante.",
  ui_story_5068_50681601_8_dialog_content = "Desculpe-me, Senhora Sheol!",
  ui_story_5068_50681601_9_dialog_content = "Ei, PlayerName! Eu não sabia que você estava aqui?",
  ui_story_5068_50681601_10_dialog_content = "Isa? E Rebecca também?",
  ui_story_5068_50681601_11_dialog_content = "Já está se sentindo melhor?",
  ui_story_5068_50681601_12_dialog_content = "Sim. Graças a Isa, eu me sinto muito melhor agora.",
  ui_story_5068_50681601_13_dialog_content = "Mas você ainda tem um longo caminho pela frente até estar totalmente curado... Argh, se ao menos eu fosse um pouco mais forte!",
  ui_story_5068_50681601_14_dialog_content = "Não diga isso, Isa! Estou grato apenas por estar junto com você de novo.",
  ui_story_5068_50681601_15_dialog_content = "Estou grato em ver que nosso \"médico sem nome\" também está se recuperando aos poucos.",
  ui_story_5068_50681601_16_dialog_content = "Por favor, não brinque assim, Sra. Sheol.",
  ui_story_5068_50681601_17_dialog_content = "Desculpe, não pude me conter ao ver vocês dois juntos assim... Mas agora que todos os envolvidos estão aqui, gostaria de relatar minhas descobertas para vocês.",
  ui_story_5068_50681601_18_dialog_content = "Afinal, você tem o direito de saber o que aconteceu com os Lobos Negros após o incidente.",
  ui_story_5068_50681601_19_dialog_content = "Mas se você preferir não ouvir sobre isso...",
  ui_story_5068_50681601_20_dialog_content = "Tudo bem, Sra. Sheol. Por favor, nos conte.",
  ui_story_5068_50681601_21_dialog_content = "Claro. Tentarei ser breve.",
  ui_story_5068_50681601_22_dialog_content = "Já coletamos provas suficientes para implicar os Lobos Negros em seu perverso plano de produzir a névoa negra. Quanto a Arte...",
  ui_story_5068_50681601_23_dialog_content = "Ela também foi exposta à névoa negra naquela noite. Onde quer que ela esteja escondida, duvido que nos cause mais problemas a partir de agora.",
  ui_story_5068_50681601_24_dialog_content = "Então, ela recebeu o que merecia! Bom, agora posso respirar um pouco mais aliviado.",
  ui_story_5068_50681601_25_dialog_content = "...",
  ui_story_5068_50681601_26_dialog_content = "Em relação à sua clínica, estou mais do que disposto a ajudar na reconstrução.",
  ui_story_5068_50681601_27_dialog_content = "Obrigado, mas não é necessário, Senhora Sheol. Você já fez mais do que o suficiente por nós.",
  ui_story_5068_50681601_28_dialog_content = "Heheh, eu esperava que o Rebecca me rejeitasse, não você.",
  ui_story_5068_50681601_29_dialog_content = "A verdade é que viemos nos despedir hoje, Sra. Sheol.",
  ui_story_5068_50681601_30_dialog_content = "Entendi... Tem certeza de que não quer ficar aqui? Não estou tentando forçá-lo a trabalhar para mim nem nada; eu ficaria mais feliz se vocês dois ficassem com a Guilda Cloudrover.",
  ui_story_5068_50681601_31_dialog_content = "Você diz isso, mas sabia exatamente o que estava em nossas mentes no momento em que entramos, não é, Senhora Sheol?",
  ui_story_5068_50681601_32_dialog_content = "Eu vi isso em seus olhos, para ser preciso... Então, não só estou perdendo Rebecca, mas também um dos meus assistentes mais úteis. Ah, que pena.",
  ui_story_5068_50681601_33_dialog_content = "Eu até ia pedir ao PlayerName para me ajudar a convencê-lo a ficar, mas o coitado não disse uma palavra desde que você entrou. Devo dizer que estou desapontado com ele.",
  ui_story_5068_50681601_34_dialog_content = "Huh? E-Eu estou...",
  ui_story_5068_50681601_35_dialog_content = "Obrigado pela sua generosa oferta, Sra. Sheol. Mas já tomamos nossa decisão.",
  ui_story_5068_50681601_36_dialog_content = "E... Obrigado por toda sua ajuda também, PlayerName. Se você não tivesse confiado em mim e ficado comigo desde o começo, eu não estaria...",
  ui_story_5068_50681601_37_dialog_content = "Sem problemas! Mas pensando bem, eu realmente não fiz muita coisa...",
  ui_story_5068_50681601_38_dialog_content = "Então, para onde vocês dois vão a seguir? Já descobriram?",
  ui_story_5068_50681601_39_dialog_content = "Em Umbraton, é sempre melhor não fazer muitas perguntas.",
  ui_story_5068_50681601_40_dialog_content = "Parece que as meninas têm um segredo para guardar.",
  ui_story_5068_50681601_41_dialog_content = "É mesmo...? Então não vou insistir mais. Mas se você tiver tempo, deveria visitar Eraveil algum dia. O bom tempo e a paisagem tranquila devem ajudar na recuperação de Rebecca.",
  ui_story_5068_50681601_42_dialog_content = "Obrigado pelo convite, PlayerName. Tenho a sensação... Nos veremos novamente em breve.",
  ui_story_5068_50681601_43_dialog_content = "Ufa...",
  ui_story_5068_50681601_44_dialog_content = "Mesmo tendo sofrido mais uma derrota... O Senhor Sombrio deve estar totalmente satisfeito com o trabalho da Guilda Cloudrover.",
  ui_story_5068_50681601_45_dialog_content = "<color=#e8d9bb>Toc toc toc..</color>",
  ui_story_5068_50681601_46_dialog_content = "Você já terminou de limpar, Isa? E você viu meus brincos em algum lugar?",
  ui_story_5068_50681601_47_dialog_content = "Hã...? O que você está olhando?",
  ui_story_5068_50681601_48_dialog_content = "Heeheehee...",
  ui_story_5068_50681601_49_dialog_content = "Isso é... um álbum de fotos? Por que só tem fotos minhas? E quando você tirou todas essas?",
  ui_story_5068_50681601_50_dialog_content = "Hã? R-Rebecca?! Você não sabe bater antes de entrar?!",
  ui_story_5068_50681601_51_dialog_content = "Mas eu bati!",
  ui_story_5068_50681601_52_dialog_content = "E-Então você deveria ter esperado eu responder!",
  ui_story_5068_50681601_53_dialog_content = "Tudo bem, entendi.",
  ui_story_5068_50681601_54_dialog_content = "Toc, toc, toc. Olá Isa, posso entrar?",
  ui_story_5068_50681601_55_dialog_content = "Tá bom, agora você está só me provocando! Mas vamos ver como você gosta disso!",
  ui_story_5068_50681601_56_dialog_content = "Hahahaha—Pare, isso faz cócegas! Me desculpe, Isa! Por favor, pare com isso!",
  ui_story_5068_50681601_57_dialog_content = "Você não vai se safar tão facilmente! Hora do meu ataque supremo!",
  ui_story_5068_50681601_58_dialog_content = "... Então, qual é o lance com todas essas fotos?",
  ui_story_5068_50681601_59_dialog_content = "Você realmente não sabe a hora de parar, né? Eu só queria documentar sua recuperação, então decidi tirar algumas fotos!",
  ui_story_5068_50681601_60_dialog_content = "Entendi. Obrigado por fazer isso por mim, Isa...",
  ui_story_5068_50681601_61_dialog_content = "Heeheehee! N-Não é nada, mesmo! Então, você realmente precisava de algo?",
  ui_story_5068_50681601_62_dialog_content = "Ainda não consigo encontrar meus brincos...",
  ui_story_5068_50681601_63_dialog_content = "Não se preocupe, eles estão bem aqui! Viu, cuidei bem deles! Quer ajuda para colocá-los?",
  ui_story_5068_50681601_64_dialog_content = "Isa... Eu realmente fiz algo para merecer que Eleanor sacrificasse a vida dela por mim?",
