  ui_story_5068_50681601_77_dialog_content = "Q... Quer dizer Sheol... E a Guilda Cloudrover?",
  ui_story_5068_50681601_78_dialog_content = "Você era um cãozinho fiel, Arte. Mas parece que você não estava satisfeito em ser apenas um cãozinho de colo.",
  ui_story_5068_50681601_79_dialog_content = "O-Claro que estava, minha senhora! Eu farei o que você pedir! Por favor, apenas me salve—",
